function modal(html,wide){const m=document.createElement('div');m.className='modal-back';m.innerHTML=`<div class="modal ${wide?'wide':''}">${html}</div>`;m.close=()=>{if(m._c)return;m._c=1;m.classList.add('out');setTimeout(()=>m.remove(),190)};m.addEventListener('mousedown',e=>{if(e.target===m)m.close()});m.addEventListener('click',e=>{if(e.target.closest('[data-x]'))m.close()});document.body.appendChild(m);return m}
