(function(){const b=document.createElement('button');b.type='button';b.id='fpForgot';b.textContent='Mot de passe oublié ?';$('#authForm').appendChild(b);
  b.onclick=()=>{const m=modal(`<h3>Réinitialiser le mot de passe</h3><p class="muted">Disponible si vous avez ajouté et vérifié un courriel ou un numéro de récupération dans les Paramètres. Seul le contact enregistré dans les paramètres de ce compte peut recevoir le code. Attention : vos anciennes conversations chiffrées de bout en bout deviendront illisibles.</p>
    <label>Nom d’utilisateur (actuel ou ancien)</label><input id="rsU"><label>Recevoir le code par</label><select id="rsK"><option value="email">Courriel</option><option value="sms">Téléphone (SMS)</option></select>
    <label id="rsEL">Courriel de récupération</label><input id="rsE"><div class="row end"><button id="rsSend">Envoyer le code</button></div>
    <div id="rsB" hidden><label>Code reçu</label><input id="rsC" inputmode="numeric" maxlength="8"><label>Nouveau mot de passe</label><input id="rsP" type="password" autocomplete="new-password"><div class="row end"><button id="rsGo">Changer le mot de passe</button></div></div><div class="row end"><button class="ghost" data-x>Fermer</button></div>`,true);
    const call=body=>sb.functions.invoke('account-mail',{body}).then(r=>{if(r.error||(r.data&&r.data.error))throw new Error((r.data&&r.data.error)||'Service indisponible');return r.data});
    const pl=()=>{const s=$('#rsK',m).value==='sms';$('#rsEL',m).textContent=s?'Numéro de récupération (format +15145551234)':'Courriel de récupération';$('#rsE',m).type=s?'tel':'email'};$('#rsK',m).onchange=pl;pl();
    const body=extra=>Object.assign({username:$('#rsU',m).value,channel:$('#rsK',m).value,email:$('#rsE',m).value,phone:$('#rsE',m).value},extra);
    $('#rsSend',m).onclick=async e=>{e.target.disabled=true;try{await call(body({action:'reset_request'}));$('#rsB',m).hidden=false;toast('Si les informations correspondent, un code a été envoyé')}catch(x){toast(errMsg(x))}e.target.disabled=false};
    $('#rsGo',m).onclick=async e=>{e.target.disabled=true;try{await call(body({action:'reset_confirm',code:$('#rsC',m).value,password:$('#rsP',m).value}));m.close();$('#fu').value=$('#rsU',m).value.trim();toast('Mot de passe changé : connectez-vous')}catch(x){toast(errMsg(x))}e.target.disabled=false}}})();
function showAuth(msg){$('#app').hidden=true;$('#auth').hidden=false;$('#authErr').textContent=msg||''}
async function signUp(u,p,p2){
  if(!/^[a-z0-9_]{3,20}$/.test(u))throw new Error("Nom d'utilisateur : 3 à 20 caractères (a-z, 0-9, _)");
  if(p.length<6)throw new Error('Mot de passe : 6 caractères minimum');
  if(p!==p2)throw new Error('Les mots de passe ne correspondent pas');
  try{const {data:okn}=await sb.rpc('name_available',{p_name:u});if(okn==='forbidden')throw new Error('Ce nom d’utilisateur n’est pas autorisé');if(okn==='taken')throw new Error("Ce nom d'utilisateur est déjà pris ou réservé")}catch(x){if(/autoris|pris/.test(x.message))throw x}
  const {data,error}=await sb.auth.signUp({email:u+DOMAIN,password:p});
  if(error)throw new Error(/registered|exists/i.test(error.message)?"Ce nom d'utilisateur est déjà pris":error.message);
  if(!data.session)throw new Error("Nom d'utilisateur déjà pris, ou confirmation par courriel active dans Supabase (à désactiver)");
  const kp=await crypto.subtle.generateKey(ECP,true,['deriveKey']);
  const pubJwk=await crypto.subtle.exportKey('jwk',kp.publicKey), privJwk=await crypto.subtle.exportKey('jwk',kp.privateKey);
  const salt=crypto.getRandomValues(new Uint8Array(16));
  const encPriv=b64e(await aesEnc(await pbkdf(p,salt),enc.encode(JSON.stringify(privJwk))));
  const uid=data.user.id;
  let r=await sb.from('user_keys').insert({user_id:uid,enc_private_key:encPriv,salt:b64e(salt)});if(r.error)throw r.error;
  r=await sb.from('profiles').insert({id:uid,username:u,public_key:pubJwk});if(r.error)throw r.error;
  await idbSet('priv:'+uid,await crypto.subtle.importKey('jwk',privJwk,ECP,false,['deriveKey']));
  try{const {data:lc}=await sb.rpc('legal_current');if(lc&&lc.version>0)await sb.rpc('legal_accept',{p_version:lc.version})}catch(e){}   /* créer un compte = adhérer aux conditions en vigueur */
}
async function loginEmail(u){u=String(u||'').trim().toLowerCase().replace(/^@/,'');try{const {data}=await sb.rpc('login_email',{p_username:u});if(data)return data}catch(e){}return u+DOMAIN}
async function signIn(u,p){
  u=String(u||'').trim().toLowerCase().replace(/^@/,'');
  if(u==='system'||u==='staff'){try{await sb.rpc('acct_code_expire')}catch(e){}}   /* un code de plus de 5 minutes n'est plus valable */
  const {data,error}=await sb.auth.signInWithPassword({email:await loginEmail(u),password:p});
  if(error)throw new Error(/invalid/i.test(error.message)?"Nom d'utilisateur ou mot de passe incorrect":error.message);
  if(data.user.email==='system'+DOMAIN||data.user.email==='staff'+DOMAIN||u==='system'||u==='staff'){await idbSet('priv:'+data.user.id,{official:1});return}
  const {data:k,error:e2}=await sb.from('user_keys').select('*').eq('user_id',data.user.id).single();
  if(e2)throw e2;
  let jwk;
  try{jwk=JSON.parse(dec.decode(await aesDec(await pbkdf(p,b64d(k.salt)),b64d(k.enc_private_key))))}
  catch(ex){
    const {data:pend}=await sb.rpc('keys_reset_pending');if(!pend)throw ex;
    const kp=await crypto.subtle.generateKey(ECP,true,['deriveKey']);
    const pubJwk=await crypto.subtle.exportKey('jwk',kp.publicKey),privJwk=await crypto.subtle.exportKey('jwk',kp.privateKey);
    const salt=crypto.getRandomValues(new Uint8Array(16));const encPriv=b64e(await aesEnc(await pbkdf(p,salt),enc.encode(JSON.stringify(privJwk))));
    const r=await sb.rpc('keys_reset',{p_enc:encPriv,p_salt:b64e(salt),p_pub:pubJwk});if(r.error)throw r.error;
    jwk=privJwk;toast('Nouvelles clés créées : vos anciennes conversations chiffrées ne sont plus lisibles');
  }
  await idbSet('priv:'+data.user.id,await crypto.subtle.importKey('jwk',jwk,ECP,false,['deriveKey']));
}
function askCode(title,label){return new Promise(res=>{let done=false;const m=modal(`<h3>${esc(title)}</h3><label>${esc(label)}</label><input id="acV" inputmode="numeric" autocomplete="one-time-code" maxlength="8"><div class="row end"><button class="ghost" id="acNo">Annuler</button><button id="acOk">Valider</button></div>`,true);
  const fin=v=>{if(done)return;done=true;m.close();res(v)};$('#acOk',m).onclick=()=>fin($('#acV',m).value.trim());$('#acNo',m).onclick=()=>fin(null);$('#acV',m).onkeydown=e=>{if(e.key==='Enter')fin($('#acV',m).value.trim())};$('#acV',m).focus()})}
async function mfaGate(){
  const {data:a}=await sb.auth.mfa.getAuthenticatorAssuranceLevel();
  if(!a||a.nextLevel!=='aal2'||a.currentLevel==='aal2')return;
  const {data:fs}=await sb.auth.mfa.listFactors();const f=(fs&&fs.totp||[]).find(x=>x.status==='verified');if(!f)return;
  for(let i=0;i<3;i++){const c=await askCode('Vérification en deux étapes','Code à 6 chiffres de votre application d’authentification');
    if(!c){await sb.auth.signOut();throw new Error('Connexion annulée')}
    const r=await sb.auth.mfa.challengeAndVerify({factorId:f.id,code:c});if(!r.error)return;toast('Code incorrect')}
  await sb.auth.signOut();throw new Error('Trop de tentatives')
}
$('#authForm').onsubmit=async e=>{
  e.preventDefault();const u=$('#fu').value.trim().toLowerCase().replace(/^@/,''),p=$('#fp').value;
  $('#authErr').textContent='';$('#authGo').disabled=true;
  try{if(authMode==='up')await signUp(u,p,$('#fp2').value);else{await signIn(u,p);await mfaGate()}await startApp()}
  catch(ex){$('#authErr').textContent=errMsg(ex);try{await sb.auth.signOut()}catch(_){}}
  $('#authGo').disabled=false;
};
async function logout(){
  const id=S.me&&S.me.id;
  try{await sb.removeAllChannels()}catch(e){}
  await sb.auth.signOut();if(id)await idbDel('priv:'+id);
  location.reload();
}

/* ================= DONNÉES ================= */
async function ensureProfiles(ids){
  const miss=[...new Set(ids)].filter(i=>i&&!S.profiles.has(i));if(!miss.length)return;
  const {data}=await sb.from('profiles').select('*').in('id',miss);(data||[]).forEach(p=>S.profiles.set(p.id,p));
}
async function loadFriends(){
  const me=S.me.id;
  const {data,error}=await sb.from('friendships').select('*').or(`requester.eq.${me},addressee.eq.${me}`);
  if(error){toast(error.message);return}
  S.friends=data||[];
  await ensureProfiles(S.friends.map(f=>f.requester===me?f.addressee:f.requester));
  renderFriends();
}
function readBase(c){return c.mode==='clear'?c.myRead:(localStorage.getItem('cm_rd_'+c.id)||'1970-01-01T00:00:00Z')}
async function refreshLast(c,withCount){
  const {data}=await sb.from('messages').select('*').eq('conversation_id',c.id).order('id',{ascending:false}).limit(1);
  c.last=data&&data[0]?await decode(c,data[0]):null;
  if(withCount){const r=await sb.from('messages').select('id',{count:'exact',head:true}).eq('conversation_id',c.id).neq('sender_id',S.me.id).neq('kind','system').gt('created_at',readBase(c));c.unread=r.count||0}
}
async function loadConvs(){
  const me=S.me.id;
  let rq=await sb.from('conversation_members').select('last_read_at,cleared_at,conversations(*)').eq('user_id',me);
  if(rq.error&&/cleared_at/.test(rq.error.message||''))rq=await sb.from('conversation_members').select('last_read_at,conversations(*)').eq('user_id',me);
  const {data:mine,error}=rq;
  if(error){toast(error.message);return}
  const list=(mine||[]).filter(r=>r.conversations&&!(r.cleared_at&&new Date(r.cleared_at)>=new Date(r.conversations.last_message_at)));const ids=list.map(r=>r.conversations.id);
  let mem=[];if(ids.length){const r=await sb.from('conversation_members').select('conversation_id,user_id,role,last_read_at').in('conversation_id',ids);mem=r.data||[]}
  await ensureProfiles(mem.map(m=>m.user_id));
  const old=S.convs,next=new Map();
  for(const r of list){const c=r.conversations,p=old.get(c.id);next.set(c.id,{...c,members:mem.filter(m=>m.conversation_id===c.id),myRead:r.last_read_at,last:p?p.last:null,unread:p?p.unread:0,_new:!p})}
  S.convs=next;
  await Promise.all([...next.values()].filter(c=>c._new).map(async c=>{delete c._new;await refreshLast(c,true)}));
  if(S.active&&!next.has(S.active))closeChat();
}
let refT;function scheduleRefresh(){clearTimeout(refT);refT=setTimeout(async()=>{await loadConvs();renderList();if(S.active)renderHeader()},400)}

/* ---------- décodage des messages ---------- */
async function decode(c,row){
  if(c.mode==='clear'||row.kind==='system'){const d={k:row.kind,t:row.body,p:row.media_path,m:null};if(row.kind==='game'){try{d.g=JSON.parse(row.body)}catch(e){d.g={title:'Résultat',lines:[]}}}if(row.kind==='image'&&!row.media_path)d.u=row.body;botDecode(row,d);if(typeof d.t==='string'&&d.t.startsWith(CALLSENT)){try{d.c=JSON.parse(d.t.slice(CALLSENT.length));d.k='call';d.t=''}catch(e){}}row._d=d;return row}
  try{row._d=JSON.parse(await decText(c.id,row.body))}catch(e){row._d={k:'text',t:'[Message chiffré illisible]',bad:true}}
  return row;
}
const NORM_N=20;
async function loadMsgs(c){
  const {data,error}=await sb.from('messages').select('*').eq('conversation_id',c.id).order('id',{ascending:false}).limit(NORM_N);
  if(error){toast(error.message);return[]}
  const rows=(data||[]).reverse();c._more=rows.length>=NORM_N;await Promise.all(rows.map(r=>decode(c,r)));rows.forEach(r=>ephArm(r,false));return rows.filter(r=>!(r._exp&&r._exp<=Date.now()));
}
const mediaCache=new Map();
function mediaUrl(c,p,m){
  const key=c.id+'|'+p;if(mediaCache.has(key))return mediaCache.get(key);
  const pr=(async()=>{
    if(c.mode==='clear')return isPriv(p)?await signedUrl(p):pubUrl(p);
    const res=await fetch(isPriv(p)?await signedUrl(p):pubUrl(p));if(!res.ok)throw new Error('média');
    const k=await getConvKey(c.id);const buf=await aesDec(k,new Uint8Array(await res.arrayBuffer()));
    return URL.createObjectURL(new Blob([buf],{type:m||'application/octet-stream'}));
  })();
  mediaCache.set(key,pr);pr.catch(()=>mediaCache.delete(key));return pr;
}

/* ================= RENDU ================= */
const EMO=/\p{Extended_Pictographic}(?:️|\p{Emoji_Modifier})?(?:‍\p{Extended_Pictographic}(?:️|\p{Emoji_Modifier})?)*/gu;
const URLRE=/\bhttps?:\/\/[^\s<>"']{3,500}/gi;
function lkHost(u){try{return new URL(u).hostname.replace(/^www\./,'')}catch(e){return ''}}
function lkCard(u){
  const h=lkHost(u);if(!h)return '';let pth='';try{const x=new URL(u);pth=(x.pathname+x.search).replace(/\/$/,'')}catch(e){}
  const yt=u.match(/(?:youtube\.com\/watch\?[^\s]*v=|youtu\.be\/|youtube\.com\/shorts\/)([A-Za-z0-9_-]{11})/);
  const img=/^https:\/\/[^\s]+\.(png|jpe?g|gif|webp|avif)(\?[^\s]*)?$/i.test(u);
  const emb=yt?`<button class="ghost lite" data-emb="yt" data-v="${yt[1]}">Lire ici</button>`:img?`<button class="ghost lite" data-emb="img" data-v="${esc(u)}">Afficher l’image</button>`:'';
  return `<div class="lcard"><a href="${esc(u)}" target="_blank" rel="noopener noreferrer nofollow"><b>${esc(h)}</b><span>${esc(pth.slice(0,70))}</span></a>${emb}</div>`;
}
function fmtText(t){
  const urls=[];t=String(t==null?'':t).replace(URLRE,m=>{let u=m,tail='';while(/[.,;:!?)\]]$/.test(u)){tail=u.slice(-1)+tail;u=u.slice(0,-1)}urls.push(u);return '\u0001'+(urls.length-1)+'\u0002'+tail});
  const s=esc(t);const n=(s.match(EMO)||[]).length;
  const only=n>0&&n<=3&&!s.replace(EMO,'').trim();
  const me=(S.profile&&S.profile.username||'').toLowerCase();
  return `<span class="${only?'big':''}">`+s.replace(EMO,m=>`<span class="emo a${m.codePointAt(0)%6}">${m}</span>`).replace(/(^|[^\w@])@([A-Za-z0-9_.-]{2,32})/g,(a,b,u)=>`${b}<span class="mention ${u.toLowerCase()===me?'me':''}">@${u}</span>`).replace(/\n/g,'<br>').replace(/\u0001(\d+)\u0002/g,(m,i)=>{const u=urls[+i];return `<a class="lnk" href="${esc(u)}" target="_blank" rel="noopener noreferrer nofollow">${esc(u.length>60?u.slice(0,57)+'…':u)}</a>`})+'</span>'+(urls.length?lkCard(urls[0]):'');
}
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('[data-emb]');if(!b)return;e.preventDefault();const w=b.closest('.lcard');
  if(b.dataset.emb==='yt')w.insertAdjacentHTML('beforeend',`<iframe class="lemb" src="https://www.youtube-nocookie.com/embed/${esc(b.dataset.v)}" allow="encrypted-media;picture-in-picture" allowfullscreen referrerpolicy="no-referrer"></iframe>`);
  else w.insertAdjacentHTML('beforeend',`<img class="lemb" src="${esc(b.dataset.v)}" alt="" referrerpolicy="no-referrer" loading="lazy">`);
  b.remove()});
function convTitle(c){if(c.hub==='system')return '@system';if(c.kind==='self')return 'Bloc-note';if(c.kind==='group')return c.name||'Groupe';const o=other(c);return dname(o&&S.profiles.get(o.user_id))}
function convAv(c,cls=''){if(c.kind==='self')return `<span class="av ${cls}" style="background:#f59e0b">${ic('note',cls==='lg'?38:20)}</span>`;if(c.kind==='group')return av(c.avatar_url,c.name||'G',cls+' grp');const p=S.profiles.get(other(c)?.user_id);return av(p?.avatar_url,p?.username,cls)}
const isOn=p=>p&&S.online.has(p.username);
function preview(c){
  const m=c.last;if(!m)return 'Aucun message';const d=m._d||{};const pre=m.sender_id===S.me.id?'Vous : ':'';
  const t=d.k==='video'?(d.loop?'GIF':'Vidéo'):d.k==='image'?(d.u?'GIF':'Photo'):d.k==='voice'?'Message vocal':d.k==='drawing'?'Dessin':d.k==='call'?'Appel':d.k==='game'?'Résultats : '+((d.g&&d.g.title)||''):(d.t||'');
  return pre+t.replace(/\s+/g,' ').slice(0,60);
}
function renderMe(){
  const p=S.profile;
  $('#meBox').innerHTML=`${av(p.avatar_url,p.username)}<div class="grow"><div style="font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(p.nickname||p.username)}</div><div class="muted" style="font-size:12px">@${esc(p.username)}</div></div><button class="icon" id="btnSet" title="Paramètres">${ic('gear')}</button>`;
  $('#btnSet').onclick=settingsModal;
}
function renderList(){
  const arr=[...S.convs.values()].filter(c=>c.hub!=='ticket').sort((a,b)=>(offU(b)-offU(a))||((a.hub==='system')-(b.hub==='system'))||(new Date(b.last_message_at)-new Date(a.last_message_at)));
  $('#list').innerHTML=arr.length?arr.map(c=>{
    const o=c.kind==='direct'?S.profiles.get(other(c)?.user_id):null;
    return `<div class="item ${c.id===S.active?'on':''}" data-id="${c.id}">${convAv(c)}<div class="grow"><div class="tt"><b>${esc(convTitle(c))}</b>${o&&isOff(o.id)?'<span class="stafftag">STAFF</span>':''}${c.mode==='e2e'?`<span class="muted" title="Chiffré">${ic('lock',14)}</span>`:''}</div><div class="pv">${isOn(o)?'<i class="dot on"></i> ':''}${esc(preview(c))}</div></div>${c.unread?`<span class="badge${c.mention?' men':''}" ${c.mention?'title="Vous avez été mentionné"':''}>${c.mention?'@ ':''}${c.unread}</span>`:''}<button class="delc" data-del="${c.id}" title="${c.kind==='group'?'Quitter et supprimer':c.kind==='self'?'Vider le Bloc-note':'Supprimer la discussion'}" aria-label="Supprimer la discussion">${ic('trash',16)}</button></div>`
  }).join(''):'<p class="muted pad">Aucune discussion. Ajoutez un ami puis démarrez une conversation.</p>';
}
$('#list').onclick=async e=>{
  const d=e.target.closest('.delc');
  if(d){
    e.stopPropagation();const c=S.convs.get(d.dataset.del);if(!c)return;
    const msg=c.kind==='group'?'Quitter ce groupe et supprimer la discussion ?':c.kind==='self'?'Vider le Bloc-note ? Les notes seront effacées.':'Supprimer cette discussion ? Les messages disparaîtront seulement pour vous.';
    if(!confirm(msg))return;
    const {data,error}=await sb.rpc('delete_conversation',{p_conv:c.id});
    if(error)return toast(/delete_conversation/.test(error.message||'')?'Appliquez d’abord le patch SQL n°2':error.message);
    if(data==='cleared'){S.msgs[c.id]=[];c.last=null;if(S.active===c.id)openConv(c.id)}
    else{S.convs.delete(c.id);delete S.msgs[c.id];if(S.active===c.id)closeChat();await loadConvs()}
    renderList();toast(data==='left'?'Vous avez quitté le groupe':data==='cleared'?'Bloc-note vidé':'Discussion supprimée');return;
  }
  const it=e.target.closest('.item');if(it)openConv(it.dataset.id)};
