const FONTS=[['Système','system-ui,-apple-system,"Segoe UI",Roboto,sans-serif'],['Serif','Georgia,"Times New Roman",serif'],['Machine','"Courier New",monospace'],['Arrondie','"Trebuchet MS","Comic Sans MS",sans-serif'],['Manuscrite','"Brush Script MT","Segoe Script",cursive'],['Large','Verdana,Geneva,sans-serif']];
const DEFT={bm:'#2f6bff',tm:'#ffffff',bo:'#e9ecf2',to:'#1b1f2a',font:FONTS[0][1],bgKind:'color',bg:'#f5f7fb'};
function themeCss(t){return t.bgKind==='image'?`center/cover no-repeat url("${String(t.bg).replace(/"/g,'')}")`:t.bg}
function applyTheme(c){
  const t={...DEFT,...(c?c.theme:{})};const el=$('#chat');
  el.style.setProperty('--bm',t.bm);el.style.setProperty('--tm',t.tm);el.style.setProperty('--bo',t.bo);el.style.setProperty('--to',t.to);
  const m=$('#msgs');m.style.background=themeCss(t);m.style.fontFamily=t.font;
}
function receipt(c,arr){
  let last=null;for(let i=arr.length-1;i>=0;i--){if(arr[i].sender_id===S.me.id&&arr[i].kind!=='system'){last=arr[i];break}}
  if(!last)return null;
  const others=c.members.filter(m=>m.user_id!==S.me.id);if(!others.length)return null;
  const seen=others.filter(m=>new Date(m.last_read_at)>=new Date(last.created_at));
  if(c.kind==='direct')return{id:last.id,text:seen.length?'Vu à '+fmtT(seen[0].last_read_at):'Envoyé à '+fmtT(last.created_at)};
  return{id:last.id,text:seen.length?'Vu par '+seen.map(m=>S.profiles.get(m.user_id)?.nickname||'@'+S.profiles.get(m.user_id)?.username).join(', '):'Envoyé à '+fmtT(last.created_at)};
}
const gifOk=u=>/^https:\/\/(media\d*|i)\.giphy\.com\//.test(String(u||''));
const gameCard=g=>`<div class="gmsg"><h4>${ic('gamepad',16)} ${esc((g&&g.title)||'Résultat')} <span class="gb">résultats</span></h4><ul>${((g&&g.lines)||[]).map(l=>`<li>${esc(l)}</li>`).join('')}</ul></div>`;
function bodyHtml(d){
  if(d.k==='game')return gameCard(d.g);
  if(d.k==='call')return `<div class="callmsg" data-s="${esc((d.c||{}).s||'')}"></div>`;
  if(d.u)return gifOk(d.u)?`<img class="pic" src="${esc(d.u)}" alt="GIF">`:'<div class="muted">[GIF non autorisé]</div>';
  if(d.k==='video')return `<video class="pic" ${d.loop?'autoplay loop muted':'controls'} playsinline preload="metadata" data-p="${esc(d.p)}" data-m="${esc(d.m||'video/webm')}"></video>`;
  if(d.k==='image'||d.k==='drawing')return `<img class="pic" data-p="${esc(d.p)}" data-m="${esc(d.m||'image/jpeg')}" alt="">`;
  if(d.k==='voice')return `${d.n?`<div class="vtitle">${esc(d.n)}</div>`:''}<audio controls preload="none" data-p="${esc(d.p)}" data-m="${esc(d.m||'audio/webm')}"></audio>`;
  return `<div>${d.bot&&d.bot.title?`<div class="btitle">${esc(d.bot.title)}</div>`:''}${fmtText(d.t||'')}</div>`;
}
function renderMsgs(force){
  const c=cur();if(!c)return;const box=$('#msgs'),arr=S.msgs[c.id]||[],clear=c.mode==='clear';
  const stick=force||S.stick;const rc=clear?receipt(c,arr):null;const keepFromBottom=box.scrollHeight-box.scrollTop;
  let html='',lastDay='',prev=null;
  for(const m of arr){
    const d=m._d||{k:'text',t:''};
    if(m.kind==='system'){html+=`<div class="sys">${esc(d.t)}</div>`;prev=null;continue}
    if(clear){const day=new Date(m.created_at).toLocaleDateString('fr-CA',{weekday:'long',day:'numeric',month:'long'});if(day!==lastDay){html+=`<div class="day">${esc(day)}</div>`;lastDay=day;prev=null}}
    const bt=d.bot||null,mine=!bt&&m.sender_id===S.me.id,p=S.profiles.get(m.sender_id);
    const showName=!!bt||c.kind==='group'&&!mine&&(!prev||prev.sender_id!==m.sender_id);
    html+=`<div data-mid="${m.id}" class="mrow ${mine?'mine':''} ${isOff(m.sender_id)?'off':''} ${c._seen&&!c._seen.has(m.id)?'in':''}">${mine?'':bt?botAvHtml(bt):av(p&&p.avatar_url,p&&p.username,'xs')}<div class="bw">${showName?`<div class="who">${bt?botWhoHtml(bt):esc(m.sender_id?gdn(c,p):'Compte supprimé')}</div>`:''}<div class="bubble${m.whisper_to?' whisper':''}${bt&&bt.men&&bt.men.includes(S.me.username)?' men':''}"${bt&&bt.st?botStyleAttr(bt.st):''}>${S.dev&&m.seq?`<span class="mseq">#${m.seq}</span>`:''}${m.whisper_to?`<div class="wsp">${m.sender_id===S.me.id?'Message privé pour @'+esc((S.profiles.get(m.whisper_to)||{}).username||'?'):'Message privé de @'+esc((p&&p.username)||'?')}</div>`:''}${bodyHtml(d)}${clear?`<span class="t">${m.edited_at?'<span class="edt">modifié</span> · ':''}${fmtT(m.created_at)}</span>`:''}${m.expires_at&&m._exp?`<span class="eph-t" data-id="${m.id}">${ephTxt(m)}</span>`:''}</div>${rc&&rc.id===m.id?`<div class="rcpt">${esc(rc.text)}</div>`:''}</div></div>`;
    prev=m;
  }
  box.innerHTML=html||'<div class="sys">Aucun message. Dites bonjour !</div>';if(c._seen)arr.forEach(m=>c._seen.add(m.id));
  $$('[data-p]',box).forEach(async el=>{try{el.src=await mediaUrl(c,el.dataset.p,el.dataset.m)}catch(e){el.alt='Média indisponible'}});
  S._prog=1;if(stick)box.scrollTop=box.scrollHeight;else box.scrollTop=Math.max(0,box.scrollHeight-keepFromBottom);requestAnimationFrame(()=>{S._prog=0});
}
$('#msgs').addEventListener('scroll',()=>{if(S._prog)return;const b=$('#msgs');S.stick=b.scrollHeight-b.scrollTop-b.clientHeight<140});
$('#msgs').addEventListener('load',()=>{if(S.stick){const b=$('#msgs');b.scrollTop=b.scrollHeight}},true);
$('#msgs').addEventListener('click',e=>{const i=e.target.closest('img.pic');if(i&&i.src){const m=modal(`<img class="lbimg" src="${esc(i.src)}" alt="">`,true);m.firstChild.style.padding='8px';m.firstChild.style.maxWidth='96vw';m.firstChild.style.background='#000'}});

/* ---------- ouverture d'une conversation ---------- */
async function openConv(id){
  const c=S.convs.get(id);if(!c)return;ephClose();
  S.active=id;S.stick=true;$('#app').classList.add('inchat');
  $('#empty').hidden=true;$('#chatBox').hidden=false;{const cbx=$('#chatBox');cbx.classList.remove('swap');void cbx.offsetWidth;cbx.classList.add('swap')}$('#picker').hidden=true;
  applyTheme(c);renderHeader();renderList();
  {const cp=document.querySelector('#chatBox .comp');if(cp)cp.style.display=c.hub==='system'?'none':'';const lm=msgLim(c);$('#in').maxLength=lm||20000}
  {const mb=$('#msgs');mb.style.visibility='hidden';mb.innerHTML='<div class="sys">Chargement…</div>'}
  let msgs;try{msgs=await loadMsgs(c)}catch(e){$('#msgs').style.visibility='';throw e}
  if(S.active!==id){$('#msgs').style.visibility='';return}
  S.msgs[id]=msgs;c._seen=new Set(msgs.map(m=>m.id));c.last=msgs[msgs.length-1]||c.last;
  {const rb=readBase(c);renderMsgs(true);scrollOldestUnread(c,rb)}markRead(c);
  if(c.kind==='direct'){const o=other(c);if(o){const {data}=await sb.from('profiles').select('*').eq('id',o.user_id).maybeSingle();if(data){S.profiles.set(data.id,data);if(S.active===id)renderHeader()}}}
}
