let mrT;
function markRead(c){
  if(!c||document.hidden)return;c.unread=0;c.mention=false;
  if(c.mode==='clear'){clearTimeout(mrT);const now=Date.now();if(!c._mr||now-c._mr>1500){c._mr=now;sb.rpc('mark_read',{p_conv:c.id}).then(()=>{c.myRead=new Date().toISOString()})}else mrT=setTimeout(()=>{c._mr=Date.now();sb.rpc('mark_read',{p_conv:c.id}).then(()=>{c.myRead=new Date().toISOString()})},800)}
  else{const lt=c.last&&c.last.created_at?new Date(c.last.created_at).getTime()+1:Date.now();localStorage.setItem('cm_rd_'+c.id,new Date(Math.max(lt,Date.parse(localStorage.getItem('cm_rd_'+c.id)||0)||0)).toISOString())}
  renderList();
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&S.active)markRead(cur())});

/* ================= ENVOI ================= */
async function sendPayload(c,pl,ttl){
  let kind,body,media=null;
  if(c.mode==='clear'&&pl.k==='call'){kind='text';body=CALLSENT+JSON.stringify(pl.c)}
  else if(c.mode==='clear'){kind=pl.k;body=kind==='game'?JSON.stringify(pl.g):(kind==='image'&&pl.u)?pl.u:(pl.t||null);media=pl.p||null;if(pl.bot||pl.fx)body=BOTSENT+JSON.stringify({bot:pl.bot,fx:pl.fx,t:pl.t||'',n:pl.n})}
  else{kind='text';body=await encText(c.id,JSON.stringify(pl))}
  let r=await sb.rpc('send_message',ttl?{p_conv:c.id,p_kind:kind,p_body:body,p_media:media,p_ttl:ttl}:{p_conv:c.id,p_kind:kind,p_body:body,p_media:media});
  if(r.error&&(r.error.code==='PGRST202'||/schema cache|could not find the function/i.test(r.error.message||''))){
    r=ttl?{error:new Error('Appliquez d’abord le patch SQL n°3 (messages éphémères)')}:await sb.from('messages').insert({conversation_id:c.id,sender_id:S.me.id,kind,body,media_path:media}).select().single();
  }
  if(r.error)throw new Error(r.error.message||'Envoi refusé');
  const data=Array.isArray(r.data)?r.data[0]:r.data;
  if(!data||data.id==null){toast('Message non envoyé');return}
  data._d=pl;ephArm(data,true);if(pl.fx)botFx(c,pl);
  const list=S.msgs[c.id]||(S.msgs[c.id]=[]);
  if(!list.some(x=>x.id===data.id)){list.push(data);c.last=data;c.last_message_at=data.created_at}
  if(S.active===c.id){S.stick=true;renderMsgs(true)}
  renderList();
}
async function cmpImage(blob,max=1280,q=.78){
  try{if(!/^image\/(png|jpeg|webp)$/.test(blob.type))return blob;
    const url=URL.createObjectURL(blob);let i;try{i=await loadImg(url)}finally{URL.revokeObjectURL(url)}
    const r=Math.min(1,max/Math.max(i.width,i.height)),cv=document.createElement('canvas');cv.width=Math.max(1,Math.round(i.width*r));cv.height=Math.max(1,Math.round(i.height*r));
    const x=cv.getContext('2d');x.imageSmoothingQuality='high';x.drawImage(i,0,0,cv.width,cv.height);
    let o=await new Promise(res=>cv.toBlob(res,'image/webp',q));if(!o||o.type!=='image/webp')o=await new Promise(res=>cv.toBlob(res,'image/jpeg',q));
    return o&&o.size<blob.size?o:blob}catch(e){return blob}}
async function cmpVideo(file,onp,maxW=640,vbps=700000){
  return new Promise((ok,ko)=>{const v=document.createElement('video');v.muted=true;v.playsInline=true;v.src=URL.createObjectURL(file);
    v.onerror=()=>ko(new Error('Vidéo illisible'));
    v.onloadedmetadata=()=>{const r=Math.min(1,maxW/v.videoWidth),w=Math.round(v.videoWidth*r/2)*2,h=Math.round(v.videoHeight*r/2)*2;
      const cv=document.createElement('canvas');cv.width=w;cv.height=h;const x=cv.getContext('2d');
      const st=cv.captureStream(24);let ac=null;try{const s=v.captureStream?v.captureStream():null;const at=s&&s.getAudioTracks()[0];if(at)st.addTrack(at)}catch(_){}
      const mt=['video/webm;codecs=vp9,opus','video/webm;codecs=vp8,opus','video/webm','video/mp4'].find(m=>window.MediaRecorder&&MediaRecorder.isTypeSupported(m));
      if(!mt)return ko(new Error('Compression vidéo non prise en charge par ce navigateur'));
      const rec=new MediaRecorder(st,{mimeType:mt,videoBitsPerSecond:vbps,audioBitsPerSecond:64000}),ch=[];
      rec.ondataavailable=e=>{if(e.data.size)ch.push(e.data)};
      rec.onstop=()=>{URL.revokeObjectURL(v.src);ok(new Blob(ch,{type:mt.split(';')[0]}))};
      let raf;const draw=()=>{x.drawImage(v,0,0,w,h);if(onp&&v.duration)onp(v.currentTime/v.duration);raf=requestAnimationFrame(draw)};
      v.onended=()=>{cancelAnimationFrame(raf);setTimeout(()=>rec.stop(),150)};
      rec.start(500);v.play().then(draw).catch(e=>ko(e))}})}
/* compression AUTOMATIQUE de tout média envoyé au serveur (chat, profil, groupes, fonds, cadres) : aucune action de l'utilisateur */
const kbs=n=>n>1048576?(n/1048576).toFixed(2)+' Mo':Math.round(n/1024)+' Ko';
async function cmpGif(blob,maxW=480){
  if(!('ImageDecoder' in window)||!window.MediaRecorder)return null;
  let dec;try{dec=new ImageDecoder({data:await blob.arrayBuffer(),type:'image/gif'});await dec.tracks.ready}catch(e){return null}
  const n=dec.tracks.selectedTrack.frameCount;if(n<2){dec.close();return null}               /* GIF fixe : traité comme une image */
  const mt=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(m=>MediaRecorder.isTypeSupported(m));if(!mt){dec.close();return null}
  const f0=(await dec.decode({frameIndex:0})).image,r=Math.min(1,maxW/Math.max(f0.displayWidth,f0.displayHeight));
  const w=Math.max(2,Math.round(f0.displayWidth*r/2)*2),h=Math.max(2,Math.round(f0.displayHeight*r/2)*2);f0.close();
  const cv=document.createElement('canvas');cv.width=w;cv.height=h;const x=cv.getContext('2d');
  const rec=new MediaRecorder(cv.captureStream(24),{mimeType:mt,videoBitsPerSecond:600000}),ch=[];rec.ondataavailable=e=>{if(e.data.size)ch.push(e.data)};
  const done=new Promise(ok=>rec.onstop=ok);rec.start(250);let t=0;
  for(let i=0;i<n&&t<30000;i++){const {image}=await dec.decode({frameIndex:i});x.fillStyle='#fff';x.fillRect(0,0,w,h);x.drawImage(image,0,0,w,h);
    const d=Math.max(30,(image.duration||100000)/1000);image.close();t+=d;await new Promise(k=>setTimeout(k,d))}
  await new Promise(k=>setTimeout(k,120));rec.stop();await done;dec.close();
  return new Blob(ch,{type:'video/webm'})}
/* renvoie {blob,mime,k} : k='video' (+loop) quand un GIF animé devient une courte vidéo en boucle */
async function autoMedia(blob,mime){
  const base=String(mime||blob.type||'').split(';')[0];
  if(base==='image/gif'){const v=await cmpGif(blob).catch(()=>null);if(v&&v.size<blob.size)return{blob:v,mime:'video/webm',k:'video',loop:1};
    const o=await cmpImage(await resizeBlob(blob,1280,.8,'image/webp').catch(()=>blob),1280,.75);return o.size<blob.size?{blob:o,mime:o.type}:{blob,mime:base}}
  if(base.startsWith('video/')){
    const du=await new Promise(ok=>{const v=document.createElement('video');v.preload='metadata';v.onloadedmetadata=()=>{ok(v.duration);URL.revokeObjectURL(v.src)};v.onerror=()=>ok(0);v.src=URL.createObjectURL(blob)});
    if(du>180)throw new Error('Vidéo trop longue (3 minutes maximum)');
    toast('Compression de la vidéo…');
    let o=null;try{o=await cmpVideo(blob)}catch(e){o=null}
    if(o&&o.size<blob.size)return{blob:o,mime:o.type.split(';')[0],k:'video'};
    if(blob.size>8*1048576)throw new Error('Vidéo impossible à compresser sur cet appareil');
    return{blob,mime:base,k:'video'}}
  if(base.startsWith('image/')&&base!=='image/svg+xml'){
    let b=blob,mm=base;if(!/^image\/(png|jpeg|webp)$/.test(base)){try{b=await resizeBlob(blob,1600,.82);mm='image/jpeg'}catch(e){return{blob,mime:base}}}
    if(b.size>15000){const o=await cmpImage(b,1600,.78);if(o.size<b.size){b=o;mm=o.type}}
    return{blob:b,mime:mm}}
  return{blob,mime:base}}
async function uploadMedia(c,blob,mime){
  const am=await autoMedia(blob,mime);blob=am.blob;mime=am.mime;
  const base=mime.split(';')[0];let path,data=blob,ct=base;
  const ext=base.startsWith('video/')?(base.includes('mp4')?'mp4':'webm'):base.includes('webp')?'webp':base.includes('png')?'png':base.includes('gif')?'gif':base.includes('mp4')?'m4a':base.includes('ogg')?'ogg':base.includes('mpeg')?'mp3':base.includes('wav')?'wav':base.startsWith('audio')?'webm':'jpg';
  if(c.mode==='e2e'){data=await encBlob(c.id,blob);ct='application/octet-stream';path=`${S.me.id}/${rid()}.bin`}
  else path=`${S.me.id}/${rid()}.${ext}`;
  path=path.replace(/\/([^/]+)$/,'/m_$1');
  const {error}=await sb.storage.from(BUCKET_P).upload(path,data,{contentType:ct,upsert:false});
  if(error)throw error;return{p:path,m:base,k:am.k,loop:am.loop};
}
async function sendImageBlob(blob,kind='image'){
  const c=cur();if(!c)return;
  try{const u=await uploadMedia(c,blob,blob.type||'image/jpeg');await sendPayload(c,u.k==='video'?{k:'video',p:u.p,m:u.m,...(u.loop?{loop:1}:{})}:{k:kind,p:u.p,m:u.m})}catch(e){toast('Envoi impossible : '+errMsg(e))}
}
const RECENT=[];
const msgLim=c=>(!c||c.hub||c.kind==='self')?0:100;
const normMsg=s=>String(s||'').replace(/\s+/g,' ').trim().toLowerCase();
async function sendText(){
  const c=cur(),ta=$('#in'),t=ta.value.trim();if(!c||!t)return;const ttl=EPH.ttl;
  if(c.hub==='system')return toast('Vous ne pouvez pas répondre à @system : utilisez @staff');
  const lim=msgLim(c);
  if(lim){
    if(t.length>lim)return toast('Message trop long : '+lim+' caractères au maximum');
    const now=Date.now(),k=normMsg(t);while(RECENT.length&&now-RECENT[0].at>300000)RECENT.shift();
    if(RECENT.filter(x=>x.k===k).length>=2){sb.rpc('spam_notice').then(()=>{},()=>{});return toast('Message identique envoyé trop souvent : non envoyé')}
    RECENT.push({k,at:now});
  }
  ta.value='';ta.style.height='auto';{const b_=$('#bSend');b_.classList.remove('fly');void b_.offsetWidth;b_.classList.add('fly')}
  if(ttl)ephClose();try{await sendPayload(c,{k:'text',t},ttl)}catch(e){ta.value=t;if(ttl){EPH.ttl=ttl;ephOpen()}toast('Envoi impossible : '+errMsg(e))}
}
$('#bSend').onclick=sendText;
$('#in').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();sendText()}});
