/* ---------- personnalisation du chat (partagée avec tous les membres) ---------- */
/* ---------- lot 11 : apparence, médaillons, blocage, discussions publiques ---------- */
const POPPY='<img class="poppy" alt="" width="20" height="20" src="assets/images/poppy.png">';
S.blk=new Map();/* id -> true si c'est moi qui ai bloque */
async function blocksLoad(){try{const {data}=await sb.rpc('blocks_me');S.blk=new Map((data||[]).map(r=>[r.user_id,!!r.mine]));S.remask&&S.remask();renderList();renderHeader()}catch(e){}}
const isBlk=id=>!!id&&S.blk.has(id);
function lookInit(m){
  const l=lookGet();const sel=$('#lkMode',m);sel.value=l.mode||'light';
  sel.onchange=()=>{const x=lookGet();x.mode=sel.value;localStorage.setItem('cm_look',JSON.stringify(x));lookApply()};
  const cols=[['bleu','Bleu','#2f6bff'],['vert','Vert','#16a34a'],['jaune','Jaune','#ca8a04'],['rouge','Rouge','#e5484d'],['orange','Orange','#f97316']];
  const box=$('#lkCol',m);const draw=()=>{const cur=lookGet().color||'bleu';box.innerHTML=cols.map(c=>`<button type="button" title="${c[1]}" data-c="${c[0]}" class="${cur===c[0]?'on':''}" style="--c:${c[2]}"></button>`).join('')};
  draw();box.onclick=e=>{const b=e.target.closest('[data-c]');if(!b)return;const x=lookGet();x.color=b.dataset.c;localStorage.setItem('cm_look',JSON.stringify(x));lookApply();draw()};
  const bb=$('#lkBlk',m);const dr=async()=>{let n=[];try{n=(await sb.rpc('blocks_names')).data||[]}catch(e){}
    bb.innerHTML=n.length?n.map(r=>`<div class="blkrow"><span class="grow">@${esc(r.username)}</span><button class="ghost lite" data-u="${esc(r.username)}">Débloquer</button></div>`).join(''):'Aucun utilisateur bloqué.'};
  dr();bb.onclick=async e=>{const u=e.target.dataset&&e.target.dataset.u;if(!u)return;const {error}=await sb.rpc('block_set',{p_username:u,p_on:false});if(error)return toast(error.message);toast('@'+u+' débloqué');await blocksLoad();dr()};
  $('#lkPub',m).onclick=publicModal;
}
async function publicModal(){
  const m=modal('<h3>Discussion publique</h3><p class="muted" style="margin:0">Il n’existe qu’une seule discussion publique, ouverte à tous et modérée par les administrateurs du site. Sans chiffrement ; seul le lien https://rromanou.github.io/Communicer/ y est accepté.</p><div id="pbL"><p class="muted">Chargement…</p></div><div class="row end"><button class="ghost" data-x>Fermer</button></div>');
  const box=$('#pbL',m);let l=[];try{const r=await sb.rpc('public_list');if(r.error)throw r.error;l=r.data||[]}catch(e){box.innerHTML='<p class="muted">'+esc(errMsg(e))+'</p>';return}
  box.innerHTML=l.length?l.map((x,i)=>`<div class="blkrow"><span class="grow"><b>${esc(x.name||'Groupe')}</b> <span class="muted">${x.members} membre${x.members>1?'s':''}</span></span>${x.joined?'<span class="tag">membre</span>':`<button class="lite" data-i="${i}">Rejoindre</button>`}</div>`).join(''):'<p class="muted">Aucune discussion publique pour le moment.</p>';
  box.onclick=async e=>{const i=e.target.dataset&&e.target.dataset.i;if(i==null)return;const {error}=await sb.rpc('public_join',{p_conv:l[i].id});if(error)return toast(error.message);toast('Discussion rejointe');m.close();await loadConvs();renderList()};
}
/* ---------- lot 12 : cadres en image ---------- */
const IFR={};
const frUrl=u=>/^https:/.test(u)?u:PBASE+'/'+(/^frames\//.test(u)?'assets/':'')+u;
async function framesLoad(){
  let l=[];try{const {data}=await sb.rpc('frames_img');l=data||[]}catch(e){return}
  let css='';
  for(const f of l){IFR[f.code]=f;const u=CSS.escape?frUrl(f.img).replace(/["\\()]/g,''):frUrl(f.img);
    if(f.cat==='photo'||f.cat==='photo_anim')css+=`.av.${f.code}{overflow:visible}.av.${f.code} img{border-radius:50%}.av.${f.code}::after{content:"";position:absolute;inset:-16.667%;background:url("${u}") center/100% 100% no-repeat;pointer-events:none;z-index:2}\n`;
    else css+=`.rfs.${f.code}{background:url("${u}") center/100% 100% no-repeat #8883;box-shadow:none!important;border-radius:4px}\n`}
  let st=document.getElementById('ifStyle');if(!st){st=document.createElement('style');st.id='ifStyle';document.head.appendChild(st)}st.textContent=css;
}
function ifrAttach(mo,code){
  const f=IFR[code];if(!f||mo.querySelector('.ifr'))return;
  mo.insertAdjacentHTML('beforeend',`<div class="ifr" style="--ifi:url('${frUrl(f.img).replace(/['"()\\]/g,'')}')"><i class="t"></i><i class="m"></i><i class="b"></i></div>`);
}
async function stFrames(m,box){
  const dl=[['tpl_photo.png','Gabarit photo (PNG fixe)'],['tpl_photo_anim.png','Gabarit photo animé (PNG animé)'],['tpl_prof.png','Gabarit profil (PNG fixe)'],['tpl_prof_anim.png','Gabarit profil animé (PNG animé)']];
  const draw=async()=>{await framesLoad();const cu=Object.values(IFR).filter(f=>f.custom);
    box.innerHTML=`<p class="muted">Cadres en image. Photo : image carrée, cercle de photo au centre (75 % du diamètre), fond transparent. Profil : image 600 x 360, bande du milieu de 40 px étirée entre le haut (160 px) et le bas (160 px). Formats : PNG, GIF, WebP ou PNG animé, 1,5 Mo maximum.</p>
    <label>Gabarits à télécharger</label><div class="row" style="flex-wrap:wrap">${dl.map(d=>`<a class="ghost lite" style="padding:6px 12px;border:1px solid var(--line);border-radius:10px;text-decoration:none;color:var(--text)" href="${PBASE}/assets/frames/${d[0]}" download="${d[0]}">${d[1]}</a>`).join('')}</div>
    <label>Importer un cadre</label>
    <div class="row"><select id="cdC"><option value="photo">Photo</option><option value="photo_anim">Photo animée</option><option value="profile">Profil</option><option value="profile_anim">Profil animé</option></select><input id="cdN" class="grow" maxlength="40" placeholder="Nom du cadre"></div>
    <div class="row" style="margin-top:6px"><input type="file" id="cdF" accept="image/png,image/gif,image/webp" class="grow"><button id="cdGo">Importer</button></div>
    <label>Cadres importés</label>${cu.length?cu.map(f=>`<div class="cadre-row"><span class="cp" style="background-image:url('${esc(frUrl(f.img))}')"></span><span class="grow">${esc(f.name)} <span class="muted">${esc({photo:'photo',photo_anim:'photo animé',profile:'profil',profile_anim:'profil animé'}[f.cat])}</span></span><span class="tag">${esc({shop:'boutique',all:'tout le monde',list:'personnes choisies'}[f.audience||'shop'])}</span><input data-fp="${esc(f.code)}" type="number" min="1" step="1" placeholder="Prix" value="${f.price||''}" style="width:82px"><button class="ghost lite" data-fps="${esc(f.code)}">Prix</button><button class="ghost lite" data-au="${esc(f.code)}">Destinataires</button><button class="ghost lite" data-rm="${esc(f.code)}">Retirer</button></div>`).join(''):'<p class="muted">Aucun cadre importé.</p>'}`};
  await draw();
  box.onclick=async e=>{const t=e.target;try{
    if(t.dataset.au){const code=t.dataset.au,f=IFR[code]||{};const mm=modal(`<h3>Décerner « ${esc(f.name||'')} »</h3><label class="row" style="color:var(--text)"><input type="radio" name="au" value="all" ${f.audience==='all'?'checked':''}> Tout le monde</label><label class="row" style="color:var(--text)"><input type="radio" name="au" value="list" ${f.audience==='list'?'checked':''}> Seulement certaines personnes</label><label class="row" style="color:var(--text)"><input type="radio" name="au" value="shop" ${!f.audience||f.audience==='shop'?'checked':''}> Boutique seulement (pass payant)</label>
      <label>Noms d'utilisateur (un par ligne ou séparés par des virgules)</label><textarea id="auU" rows="4" style="width:100%"></textarea><label class="row" style="color:var(--text)"><input type="checkbox" id="auR"> Retirer le cadre à ces personnes</label><div class="row end"><button class="ghost" data-x>Annuler</button><button id="auGo">Appliquer</button></div>`);
      $('#auGo',mm).onclick=async()=>{try{const mode=mm.querySelector('[name=au]:checked').value;const us=$('#auU',mm).value.split(/[\s,;]+/).map(x=>x.trim()).filter(Boolean);if(mode==='list'&&!us.length&&f.audience!=='list')throw new Error('Indiquez au moins un nom');const n=await rpcd('frame_audience',{p_code:code,p_mode:mode,p_users:mode==='list'?us:[],p_revoke:$('#auR',mm).checked});mm.close();toast(mode==='list'?n+' personne(s) traitée(s)':'Destinataires mis à jour');cosReset();await draw()}catch(x){toast(errMsg(x))}};return}
    if(t.dataset.fps){const iv=box.querySelector(`[data-fp="${t.dataset.fps}"]`).value.trim();await rpcd('frame_price_set',{p_code:t.dataset.fps,p_price:iv?Number(iv):null});toast(iv?'Prix fixé : '+iv+' jetons (versés au commandant vendeur)':'Cadre non vendu');cosReset();return draw()}
    if(t.dataset.rm){if(!confirm('Retirer ce cadre ? Il sera enlevé des profils qui l’utilisent.'))return;await rpcd('frame_remove',{p_code:t.dataset.rm});toast('Cadre retiré');cosReset();return draw()}
    if(t.id==='cdGo'){
      const f=$('#cdF',box).files[0],cat=$('#cdC',box).value,nm=$('#cdN',box).value.trim();
      if(!nm)throw new Error('Donnez un nom au cadre');if(!f)throw new Error('Choisissez une image');
      if(f.size>1500000)throw new Error('Image trop lourde (1,5 Mo maximum)');
      const ext={'image/png':'png','image/gif':'gif','image/webp':'webp'}[f.type];if(!ext)throw new Error('Format non accepté (PNG, GIF ou WebP)');
      const dim=await new Promise((ok,ko)=>{const u=URL.createObjectURL(f),im=new Image();im.onload=()=>{URL.revokeObjectURL(u);ok([im.naturalWidth,im.naturalHeight])};im.onerror=()=>ko(new Error('Image illisible'));im.src=u});
      const r=dim[0]/dim[1];
      if(cat.startsWith('photo')&&Math.abs(r-1)>.02)throw new Error('Un cadre de photo doit être carré (gabarit 512 x 512)');
      if(cat.startsWith('profile')&&Math.abs(r-600/360)>.03)throw new Error('Un cadre de profil doit être au format 600 x 360');
      t.disabled=true;
      try{const path=await uploadPublic(f,ext,f.type);await rpcd('frame_import',{p_cat:cat,p_name:nm,p_img:pubUrl(path)});toast('Cadre importé');cosReset();await draw()}finally{t.disabled=false}
    }}catch(x){toast(errMsg(x))}};
}
