function itemExtra(k,it,ended){
  const sideN=['Pour','Contre'];
  if(k==='debate'){
    const a=(it.data.args||[]);
    return `<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:6px">${[0,1].map(s=>`<div><div class="muted"><b>${sideN[s]}</b></div>${a.filter(x=>x.s===s).map(x=>`<div style="padding:4px 0;border-top:1px solid var(--line)">${esc(x.t)} <span class="muted">@${esc(x.u)}</span></div>`).join('')||'<span class="muted">—</span>'}</div>`).join('')}</div>`+(ended?'':`<div class="row" style="margin-top:6px"><select data-as="${it.id}"><option value="0">Pour</option><option value="1">Contre</option></select><input class="grow" maxlength="300" data-at="${it.id}" placeholder="Votre argument"><button class="lite" data-ap="${it.id}">Ajouter</button></div>`);
  }
  if(k==='challenge')return `<div class="muted">${esc(it.data.desc||'')}${it.due?' · jusqu’au '+esc(fmtDt(it.due)):''}</div>`;
  return '';
}
const GA_FREE=[['link','Album'],['suggest','Suggestions'],['debate','Débats'],['challenge','Défis'],['story','Histoire'],['vote','Votes'],['vault','Coffre'],['ach','Succès'],['recap','Bilan'],['roul','Roulette'],['wait','Salle d’attente']];
async function gaSpecial(m,c,st,kind,box){
  if(kind==='ach'){const l=await rpcd('achv_me',{p_conv:c.id});box.innerHTML='<p class="muted">Succès secrets : les conditions restent cachées tant que vous ne les avez pas atteintes.</p>'+l.map(a=>`<div class="blkrow"><span class="grow">${a.unlocked?`<b>${esc(a.name)}</b><div class="muted">${esc(a.desc)}</div>`:'<b>???</b><div class="muted">Succès secret</div>'}</span><span class="tag">${a.unlocked?'débloqué':'verrouillé'}</span></div>`).join('')}
  else if(kind==='recap'){const r=await rpcd('group_recap',{p_conv:c.id});const mx=Math.max(1,...r.days.map(x=>x.n));
    box.innerHTML=`<p>Cette semaine, vous avez écrit <b>${nfmt(r.mine)}</b> message${r.mine>1?'s':''} dans ce groupe (semaine précédente : ${nfmt(r.prev)}).</p><p>Le groupe en a échangé ${nfmt(r.group)} · ${r.rank?`vous êtes n° <b>${r.rank}</b> en activité`:'vous n’avez pas encore écrit cette semaine'}.</p>
      <div style="display:flex;align-items:flex-end;gap:6px;height:80px">${r.days.map(x=>`<div style="flex:1;text-align:center"><div style="background:var(--accent);height:${Math.max(4,Math.round(x.n/mx*64))}px;border-radius:3px" title="${x.n}"></div><div class="muted" style="font-size:11px">${esc(String(x.d).slice(5))}</div></div>`).join('')||'<span class="muted">Aucune activité.</span>'}</div>`}
  else if(kind==='roul'){
    const names=Object.entries(GAMES).filter(([k,g])=>g.conv&&g.conv.includes('group')).map(([k,g])=>g.name);
    box.innerHTML=`<p class="muted">Tirez au sort le prochain jeu du groupe (${names.length} jeux disponibles).</p><div id="roR" style="font-size:22px;font-weight:700;text-align:center;padding:18px 0;min-height:30px">?</div><div class="row" style="justify-content:center"><button id="roGo">Lancer la roulette</button><button class="ghost" id="roSay" disabled>Proposer au groupe</button></div>`;
    let pick='';$('#roGo',box).onclick=()=>{let n=0;const iv=setInterval(()=>{pick=names[Math.floor(Math.random()*names.length)];$('#roR',box).textContent=pick;if(++n>16){clearInterval(iv);$('#roSay',box).disabled=false}},70)};
    $('#roSay',box).onclick=()=>{const ta=$('#in');if(ta){ta.value='Roulette des jeux : on joue à « '+pick+' » !';ta.focus()}m.close()}}
  else if(kind==='wait'){
    let w=null;try{w=(await rpcd('gi_list',{p_conv:c.id,p_kind:'waitroom'}))[0]}catch(e){}
    box.innerHTML=`<p class="muted">Message et couleur affichés dans la salle d’appel du groupe tant qu’il n’y a personne d’autre.</p><div style="border-radius:12px;padding:20px;text-align:center;color:#fff;background:${esc(w?w.data.color:'#1f2937')}">${esc(w?w.title:'Aucune salle d’attente personnalisée.')}</div>`+(st.admin?`<input id="wrT" maxlength="200" placeholder="Message d’accueil" value="${esc(w?w.title:'')}" style="margin-top:8px"><div class="row" style="margin-top:6px"><input type="color" id="wrC" value="${esc(w?w.data.color:'#1f2937')}"><button id="wrS" class="grow">Enregistrer</button></div>`:'');
    const b=$('#wrS',box);if(b)b.onclick=async()=>{try{await rpcd('gi_add',{p_conv:c.id,p_kind:'waitroom',p_title:$('#wrT',box).value,p_data:{color:$('#wrC',box).value}});toast('Salle d’attente enregistrée');gaSpecial(m,c,st,kind,box)}catch(e){toast(errMsg(e))}}}
}
/* salle d'attente personnalisée et mode présentation dans les appels de groupe */
const WR={};
async function wrLoad(cid){if(WR[cid]!==undefined)return WR[cid];WR[cid]=null;try{const l=await rpcd('gi_list',{p_conv:cid,p_kind:'waitroom'});WR[cid]=l[0]?{t:l[0].title,c:l[0].data.color}:null}catch(e){}return WR[cid]}
function presApply(){
  const ss=S.sess,r=document.getElementById('room');if(!ss||!r||ss.game!=='appel')return;
  r.classList.toggle('pres',!!ss.pin);
  document.querySelectorAll('#rmTiles .tile').forEach(t=>t.classList.toggle('pin',!!ss.pin&&t.dataset.u===ss.pin));
  const b=document.getElementById('rmPres');if(b)b.textContent=ss.pin===S.me.id?'Arrêter la présentation':'Présenter';
}
async function wrRender(){
  const ss=S.sess;if(!ss||ss.game!=='appel')return;const st=document.getElementById('rmStage');if(!st)return;
  let b=document.getElementById('wrBox');const alone=(ss.players||[]).length<2;
  if(!alone){if(b)b.remove();return}
  const w=await wrLoad(ss.conv);if(!w||!document.getElementById('rmStage'))return;
  if(!b){b=document.createElement('div');b.id='wrBox';b.style.cssText='margin:12px;padding:22px;border-radius:14px;text-align:center;color:#fff;font-size:18px';st.prepend(b)}
  b.style.background=w.c;b.textContent=w.t;
}
{const _rr=renderRoom;renderRoom=function(){_rr.apply(this,arguments);try{presApply();wrRender()}catch(e){}}}
function presToggle(){const ss=S.sess;if(!ss)return;ss.pin=ss.pin===S.me.id?null:S.me.id;rsend('pres',{u:ss.pin},ss);presApply()}

