  const m=modal(`<h3>${free?'Actions du groupe':c?'Outils du groupe':'Sondages du système'}</h3><div class="row bmT" id="giT"></div><div id="giC"></div><div class="row end"><button class="ghost" data-x>Fermer</button></div>`,true);
  const box=$('#giC',m);
