  pur:{name:'Test de pureté',desc:'100 questions, un score sur 100. Seul ; le résultat s’affiche sur votre profil.',icon:'heartp',conv:['self'],min:1,max:1,local:true,solo:true,init:PUR.game.init,reduce:PUR.game.reduce,leave:PUR.game.leave,result:PUR.game.result,mount:mountPUR}
