/* ================= MISE À L'ÉCHELLE DES JEUX (aucun défilement) ================= */
function fitHost(stage){
  let h=stage.querySelector(':scope>.rm-fit-h');
  if(h)return h.firstChild;
  stage.innerHTML='';
  h=document.createElement('div');h.className='rm-fit-h';
  const inner=document.createElement('div');inner.className='rm-fit';h.appendChild(inner);stage.appendChild(h);
  let raf=0,last='';
  const fit=()=>{
    raf=0;if(!document.body.contains(stage)||!stage.clientWidth)return;
    const cs=getComputedStyle(stage);
    const W=stage.clientWidth-parseFloat(cs.paddingLeft)-parseFloat(cs.paddingRight);
    const H=stage.clientHeight-parseFloat(cs.paddingTop)-parseFloat(cs.paddingBottom);
    if(W<40||H<40)return;
    let k=1,mw=W,w=0,hh=0;
    for(let i=0;i<5;i++){
      inner.style.maxWidth=Math.round(mw)+'px';
      w=Math.max(inner.offsetWidth,inner.scrollWidth);hh=Math.max(inner.offsetHeight,inner.scrollHeight);
      const nk=Math.min(1,W/Math.max(1,w),H/Math.max(1,hh));
      if(nk>=.999){k=1;break}
      if(i>0&&Math.abs(nk-k)<.01){k=nk;break}
      k=nk;mw=W/k;
    }
    k=Math.max(.45,k);
    const key=[k.toFixed(3),Math.round(w),Math.round(hh),Math.round(W),Math.round(H)].join();
    if(key===last)return;last=key;
    inner.style.transform=k<.999?`scale(${k})`:'none';
    h.style.width=Math.ceil(w*k)+'px';h.style.height=Math.ceil(hh*k)+'px';
  };
  const soon=()=>{if(!raf)raf=requestAnimationFrame(fit)};
  const ro=new ResizeObserver(soon);ro.observe(inner);ro.observe(stage);
  const mo=new MutationObserver(soon);mo.observe(inner,{childList:true,subtree:true,characterData:true});
  h._fit=soon;h._off=()=>{ro.disconnect();mo.disconnect()};
  addEventListener('resize',soon);
  return inner;
}

