/* ================= Patch 6 (salle) : appels de groupe, bots dans l'appel, pause, exclusion, audio ================= */
const rbots=ss=>ss.bots||(ss.bots=new Set());
const roomInsts=()=>{const ss=S.sess;return ss?[...BOT.inst.values()].filter(i=>i.c.id===ss.conv):[]};
const roomInst=u=>roomInsts().find(i=>i.meta.username===u);
function botPost(inst,name,data){try{inst.port.postMessage({t:'ev',name,data:data||{}})}catch(e){}}

