    $('#apP',root).innerHTML=api.players().map(u=>{const p=S.profiles.get(u);return `<span class="lb-p ok">${av(p&&p.avatar_url,p&&p.username,'xs')}<span>${esc(api.name(u))}</span></span>`}).join('');
    const ss=S.sess;$('#apB',root).innerHTML=ss?[...rbots(ss)].map(u=>{const i=roomInst(u);return `<span class="lb-p ok botp">${ic('robot',16)}<span>${esc(i?botNameOf(i.meta):u)}</span></span>`}).join(''):'';
    $('#apN',root).textContent=AUD.cur&&AUD.cur.title?'Musique : '+AUD.cur.title:'';
