  $('#sbIps',box).onclick=()=>go(sb.rpc('staff_ban_user_ips',{p_username:$('#sbU',box).value,p_secs:+$('#sbS',box).value||0,p_reason:$('#sbR',box).value}));
  box.onclick=e=>{const u=e.target.dataset&&e.target.dataset.u;if(u)go(sb.rpc('staff_unban',{p_id:+u}))};
