/* ================= Patch 9 : hiérarchie de l'administration ================= */
const ROLES={pt_student:'Élève administrateur à temps partiel',pt_admin:'Administrateur à temps partiel',moderator:'Administrateur élève',admin:'Administrateur',chief:'Chef des administrateurs',commander:'Commandant'};
const RANKS={pt_student:1,pt_admin:1,moderator:1,admin:2,chief:3,commander:4};
const RK=()=>RANKS[S.staff]||0;
let STAFF_ROLES={},STAFF_ROLES_AT=0;
async function staffRolesLoad(force){
  if(!force&&Date.now()-STAFF_ROLES_AT<300000)return STAFF_ROLES;
  try{const {data}=await sb.rpc('staff_public_roles');if(data){STAFF_ROLES=data;STAFF_ROLES_AT=Date.now()}}catch(e){}
  return STAFF_ROLES;
}
/* badge de rôle dans le profil */
const _opStaff=openProfile;
openProfile=async function(un,push){
  const r=await _opStaff.apply(this,arguments);
  try{
    const u=String(un||'').toLowerCase().replace(/^@/,'');const roles=await staffRolesLoad();const role=roles[u];
    const hd=$('.pf-modal .pf-hd .grow');
    if(role&&hd&&!hd.querySelector('.rbadge')){const b=document.createElement('span');b.className='rbadge r-'+role;b.textContent=ROLES[role];hd.querySelector('h3').after(b)}
  }catch(e){}
  return r;
};
/* initialisation, activité réelle et application des règles */
const _diStaff=devInit;
devInit=async function(){
  await _diStaff.apply(this,arguments);
  if(!S.staff)return;
  S.rank=RK();staffRolesLoad(true);
  try{await sb.rpc('staff_tick')}catch(e){}
  try{const {data}=await sb.rpc('dev_info');if(data)S.staff=data.staff||null}catch(e){}
  staffBeatStart();logAlertCheck();
};
let STAFF_LAST=Date.now(),STAFF_BEAT=null;
function staffBeatStart(){
  if(STAFF_BEAT)return;
  ['mousemove','keydown','click','scroll','touchstart'].forEach(ev=>addEventListener(ev,()=>{STAFF_LAST=Date.now()},{passive:true}));
  STAFF_BEAT=setInterval(async()=>{
    if(!S.staff||document.visibilityState!=='visible'||!document.hasFocus()||Date.now()-STAFF_LAST>60000)return;
    try{await sb.rpc('staff_beat',{p_secs:30})}catch(e){}
  },30000);
  setInterval(()=>{if(S.staff)sb.rpc('staff_tick').then(()=>{},()=>{})},600000);
}
/* ---------- utilitaires d'affichage ---------- */
const stBar=(label,v,need,unit)=>{const p=Math.max(0,Math.min(100,need?v/need*100:0));return `<div class="pgbar"><div class="pgl"><span>${esc(label)}</span><b>${typeof v==='number'?Math.round(v*10)/10:v}${unit?' '+unit:''} / ${need}${unit?' '+unit:''}</b></div><div class="pgt"><i style="width:${p}%" class="${p>=100?'ok':''}"></i></div></div>`};
const stRing=(label,v,need)=>{const p=Math.max(0,Math.min(1,need?v/need:0)),R=26,C=2*Math.PI*R;return `<div class="pgring"><svg width="68" height="68" viewBox="0 0 68 68"><circle cx="34" cy="34" r="${R}" class="rb"/><circle cx="34" cy="34" r="${R}" class="rf ${p>=1?'ok':''}" stroke-dasharray="${C}" stroke-dashoffset="${C*(1-p)}" transform="rotate(-90 34 34)"/><text x="34" y="38" text-anchor="middle">${Math.round(p*100)}%</text></svg><span>${esc(label)}</span></div>`};
const stLeft=d=>{if(!d)return '';const s=Math.max(0,(new Date(d)-Date.now())/1000);const j=Math.floor(s/86400),h=Math.floor(s%86400/3600),mn=Math.floor(s%3600/60);return j?`${j} j ${h} h`:`${h} h ${mn} min`};
const stWords=t=>(String(t||'').trim().match(/\S+/g)||[]).length;
/* ---------- sanctions, avertissements, modération de profil ---------- */
const CAS_N={warn:'Avertissement',sanction:'Sanction',ban_temp:'Bannissement temporaire',ban_perm:'Bannissement permanent',ban_erase:'Ban supprimé',rights:'Droit retiré',profile:'Profil modifié'};
const casHtml=d=>d.length?d.map(x=>`<div class="cas-row"><b>${esc(CAS_N[x.kind]||x.kind)} · ${esc(fmtDt(x.at))}${x.consumed?' · comptabilisé':''}</b>${esc(x.reason)}${x.message?'<br><span class="muted">'+esc(x.message)+'</span>':''}<br><span class="muted">par @${esc(x.by||'?')}</span></div>`).join(''):'<p class="muted">Casier vierge.</p>';
async function stSanc(m,box){
  box.innerHTML=`<div class="row"><input id="saU" class="grow" placeholder="@utilisateur"><button class="ghost lite" id="saC">Voir le casier</button></div>
    <label>Avertissement ou sanction</label><input id="saR" placeholder="Raison (obligatoire)"><textarea id="saM" rows="2" placeholder="Message joint (obligatoire pour une sanction)" style="margin-top:6px"></textarea>
    <div class="row end"><button class="ghost lite" id="saW">Avertir (3 avertissements = bannissement de 3 jours)</button><button class="lite" id="saS">Sanctionner</button></div>
    <label>Modifier le profil</label><div class="row"><select id="saA" class="grow"><option value="photo">Supprimer la photo</option><option value="nickname">Supprimer le surnom</option><option value="username">Remplacer le nom d’utilisateur (user[n])</option><option value="bio">Supprimer la description</option><option value="bg">Supprimer le fond de profil</option></select><label class="row" style="margin:0"><input type="checkbox" id="saK"> Renommage gratuit</label><button class="lite" id="saP">Appliquer</button></div>
    <div id="saO"></div>`;
  const u=()=>$('#saU',box).value.trim(),r=()=>$('#saR',box).value.trim();
  const run=async(fn,args,ok)=>{try{const x=await rpcd(fn,args);toast(ok(x));return x}catch(e){toast(errMsg(e))}};
  $('#saC',box).onclick=async()=>{try{$('#saO',box).innerHTML=casHtml(await rpcd('casier_of',{p_username:u()}))}catch(e){toast(errMsg(e))}};
  $('#saW',box).onclick=async()=>{const x=await run('warn_issue',{p_username:u(),p_reason:r(),p_message:$('#saM',box).value.trim()||null},x=>x.banned?'Avertissement 3/3 : bannissement de 3 jours':'Avertissement '+x.count+'/3');if(x)$('#saC',box).click()};
  $('#saS',box).onclick=async()=>{if(await run('sanction_issue',{p_username:u(),p_reason:r(),p_message:$('#saM',box).value.trim()},()=>'Sanction enregistrée'))$('#saC',box).click()};
  $('#saP',box).onclick=async()=>{const a=$('#saA',box).value;if(a==='username'&&!confirm('Remplacer le nom d’utilisateur par userN (N est un numéro) ?'))return;if(await run('profile_mod',{p_username:u(),p_action:a,p_reason:r(),p_credit:$('#saK',box).checked},()=>'Profil modifié'))$('#saC',box).click()};
}
/* ---------- annonces du système et support du staff ---------- */
const SYS={unread:0,staffOpen:0,timer:null};
async function sysPoll(){try{SYS.unread=await rpcd('world_unread');if(S.staff)SYS.staffOpen=await rpcd('support_open_count');renderList()}catch(e){}}
function sysInit(){clearInterval(SYS.timer);sysPoll();SYS.timer=setInterval(sysPoll,60000)}
const _rlS=renderList;
renderList=function(){
  _rlS.apply(this,arguments);
  const l=$('#list');if(!l||!S.me)return;
  l.querySelectorAll('.sysitem').forEach(x=>x.remove());
  const tk=[...S.convs.values()].filter(c=>c.hub==='ticket'),un=tk.reduce((n,c)=>n+(c.unread||0),0)+(S.staff?SYS.staffOpen:0);
  const html=`<div class="item sysitem staff" data-sys="staff"><span class="av" style="background:#16a34a;color:#fff;display:inline-flex;align-items:center;justify-content:center;font-weight:700">S</span><div class="grow"><div class="tt"><b>@staff</b></div><div class="pv">${tk.length?tk.length+' discussion'+(tk.length>1?'s':''):'Contacter l’équipe'}${S.staff&&SYS.staffOpen?' · '+SYS.staffOpen+' à réclamer':''}</div></div>${un?`<span class="badge">${un}</span>`:''}</div>`;
  const r=l.querySelector('.rmn-item');r?r.insertAdjacentHTML('beforebegin',html):l.insertAdjacentHTML('beforeend',html);
};
document.addEventListener('click',e=>{const it=e.target.closest&&e.target.closest('#list .sysitem');if(!it)return;e.stopImmediatePropagation();supportOpen()},true);
async function worldOpen(){
  const d=await rpcd('world_list');const last=d.last;
  const m=modal(`<h3>@system</h3><p class="muted">Messages du système : récompenses, jetons, avertissements, annonces de l’équipe. Vous ne pouvez pas y répondre ; utilisez @staff pour écrire à l’équipe.</p><div id="wmL">${d.rows.map(r=>`<div class="wm ${r.id>last?'new':''}"><small>${esc(fmtDt(r.at))}${r.all?' · annonce à tous':''}${r.by&&r.by!=='system'?' · @'+esc(r.by):''}</small><div style="white-space:pre-wrap">${esc(r.body)}</div></div>`).join('')||'<p class="muted">Aucun message.</p>'}</div><div class="row end"><button class="ghost" data-x>Fermer</button></div>`,true);
  try{await rpcd('world_mark_read');SYS.unread=0;renderList()}catch(e){}
}
const SUBJ=['Problème de compte','Bogue','Signaler un utilisateur','Paiement ou jetons','Contestation','Autre'];
async function openTicketConv(conv){
  if(!conv)return toast('Conversation introuvable');
  if(!S.convs.has(conv)){await loadConvs();renderList()}
  if(!S.convs.has(conv))return toast('Conversation introuvable');
  openConv(conv);
}
async function supportOpen(){
  const m=modal(`<h3>@staff</h3><div id="spB"></div><div class="row end"><button class="ghost" data-x>Fermer</button></div>`,true);const box=$('#spB',m);let LIST=[];
  const render=async()=>{
    const mine=await rpcd('support_mine');LIST=[];if(RK()>=1){try{LIST=await rpcd('support_list')}catch(e){}}const r=RK();
    const st={open:'En attente',claimed:'Prise en charge',closed:'Fermée'};
    const todo=LIST.filter(x=>!x.mine&&x.status==='open'),mineS=LIST.filter(x=>x.mine);
    box.innerHTML=`<p class="muted">Écrivez à l’équipe. Un administrateur réclamera votre demande et vous répondra dans la conversation.</p><button id="spNew">Nouvelle demande</button>
      <label>Mes demandes</label>${mine.length?mine.map(x=>`<div class="shrow2" data-c="${esc(x.conv||'')}" style="cursor:pointer"><div class="grow"><b>${esc(x.ref)} · ${esc(x.subject)}</b><small>${st[x.status]||x.status}</small></div></div>`).join(''):'<p class="muted">Aucune demande.</p>'}
      ${r>=1?`<label>Discussions que je supervise</label>${mineS.length?mineS.map(x=>`<div class="shrow2" data-c="${esc(x.conv||'')}" style="cursor:pointer"><div class="grow"><b>${esc(x.ref)} · ${esc(x.subject)}</b><small>@${esc(x.user)}</small></div></div>`).join(''):'<p class="muted">Aucune.</p>'}
      <label>Demandes à réclamer</label>${todo.length?todo.map(x=>`<div class="cas-row" data-r="${esc(x.ref)}"><b>${esc(x.ref)} · ${esc(x.subject)} · @${esc(x.user)}</b>${x.about?'Concerne @'+esc(x.about)+'<br>':''}<span class="muted">${esc(x.first||'')}</span>
        <div class="row" style="margin-top:6px"><button class="ghost lite" data-a="peek">Consulter</button>${r>=2?`<button class="lite green" data-a="claim">Réclamer</button>${x.student_pending?`<button class="lite orange" data-a="claimS">Réclamer avec l’Administrateur Élève @${esc(x.student)}</button>`:''}`:''}${r===1&&!x.student?'<button class="lite orange" data-a="req">Demander à réclamer avec un administrateur</button>':''}${x.req_mine?'<span class="tag">demande envoyée</span>':''}</div></div>`).join(''):'<p class="muted">Aucune demande en attente.</p>'}`:''}`;
    SYS.staffOpen=todo.length;renderList()};
  await render();
  box.onclick=async e=>{
    const t=e.target;
    if(t.id==='spNew'){box.innerHTML=`<label>Sujet</label><select id="spS">${SUBJ.map(s=>`<option>${esc(s)}</option>`).join('')}</select><label>Utilisateur concerné (facultatif)</label><input id="spA" placeholder="@utilisateur"><label>Description</label><textarea id="spD" rows="5" maxlength="2000" placeholder="Décrivez précisément la situation."></textarea><div class="row end"><button class="ghost" id="spBack">Retour</button><button id="spGo">Envoyer</button></div>`;return}
    if(t.id==='spBack')return render();
    if(t.id==='spGo'){try{const ref=await rpcd('support_create',{p_subject:$('#spS',box).value,p_body:$('#spD',box).value,p_about:$('#spA',box).value||null});await loadConvs();renderList();const mine=await rpcd('support_mine');const x=mine.find(y=>y.ref===ref);toast('Demande '+ref+' envoyée');m.close();if(x)openTicketConv(x.conv)}catch(x){toast(errMsg(x))}return}
    const a=t.dataset&&t.dataset.a;
    if(a){const ref=t.closest('[data-r]').dataset.r;try{
      if(a==='peek')return ticketPeek(ref);
      if(a==='req'){await rpcd('support_student_req',{p_ref:ref});toast('Demande envoyée');return render()}
      await rpcd('support_claim',{p_ref:ref,p_with_student:a==='claimS'});await loadConvs();renderList();const x=(await rpcd('support_list')).find(y=>y.ref===ref);toast('Demande réclamée');m.close();if(x)openTicketConv(x.conv)}catch(x){toast(errMsg(x));render()}return}
    const row=t.closest('[data-c]');if(row&&row.dataset.c){m.close();openTicketConv(row.dataset.c)}};
}
async function ticketPeek(ref){
  const t=await rpcd('support_peek',{p_ref:ref});
  modal(`<h3>${esc(t.ref)} · ${esc(t.subject)}</h3><p class="muted">Demande de @${esc(t.user)}${t.about?' · concerne @'+esc(t.about):''} · lecture seule</p><div style="max-height:320px;overflow:auto">${t.msgs.map(x=>`<div class="tk-msg us"><small>@${esc(x.who||'?')} · ${esc(fmtDt(x.at))}</small><br>${esc(x.body)}</div>`).join('')}</div><div class="row end"><button class="ghost" data-x>Fermer</button></div>`,true);
}
async function ticketView(box,ref,back,staffView){
  const draw=async()=>{const t=await rpcd('support_thread',{p_ref:ref});
    box.innerHTML=`<div class="row"><button class="ghost lite" id="tkB">Retour</button><b class="grow">${esc(t.ref)} · ${esc(t.subject)}${t.user?' · '+(staffView?'STAFF (@'+esc(t.user)+')':'@'+esc(t.user)):''}</b></div>
      ${t.about?`<p class="muted">Utilisateur concerné : @${esc(t.about)}</p>`:''}<p class="muted">${t.status==='open'?'En attente d’un administrateur.':t.status==='closed'?'Demande fermée.':'Prise en charge par @'+esc(t.claimed_by||'?')+(t.student?' avec l’administrateur élève @'+esc(t.student):'')}</p>
      <div id="tkM" style="max-height:300px;overflow:auto">${t.msgs.map(x=>`<div class="tk-msg ${t.mine?(x.staff?'st':'me'):(x.staff?'me':'us')}"><small>${x.staff?'Staff':'Demandeur'} · ${esc(fmtDt(x.at))}</small><br>${esc(x.body)}</div>`).join('')}</div>
      ${t.can_write?`<textarea id="tkT" rows="2" maxlength="2000" placeholder="Votre message"></textarea><div class="row end">${t.can_close?'<button class="ghost lite" id="tkX">Fermer la demande</button>':''}<button id="tkS">Envoyer</button></div>`:(t.can_close?'<div class="row end"><button class="ghost lite" id="tkX">Fermer la demande</button></div>':'')}`;
    const mm=$('#tkM',box);if(mm)mm.scrollTop=mm.scrollHeight;
    $('#tkB',box).onclick=back;
    const s=$('#tkS',box);if(s)s.onclick=async()=>{const v=$('#tkT',box).value.trim();if(!v)return;try{await rpcd('support_say',{p_ref:ref,p_body:v});draw()}catch(x){toast(errMsg(x))}};
    const x=$('#tkX',box);if(x)x.onclick=async()=>{if(!confirm('Fermer cette demande ?'))return;try{await rpcd('support_close',{p_ref:ref});toast('Demande fermée');back()}catch(e){toast(errMsg(e))}};
  };
  await draw();
}
async function stSupport(m,box){
  const r=RK();const draw=async()=>{const L=await rpcd('support_list');
    box.innerHTML=`<p class="muted">Demandes ouvertes et en cours. Une demande réclamée ne peut plus l’être ; tout le personnel peut la consulter sans écrire.</p>`+(L.map(x=>`<div class="cas-row" data-r="${esc(x.ref)}"><b>${esc(x.ref)} · ${esc(x.subject)} · @${esc(x.user)}</b>${x.about?'Concerne @'+esc(x.about)+'<br>':''}<span class="muted">${x.status==='open'?'En attente':'Réclamée par @'+esc(x.claimed_by||'?')+(x.student?' avec l’élève @'+esc(x.student):'')} · ${esc(fmtDt(x.at))}</span>
      <div class="row" style="margin-top:6px"><button class="ghost lite" data-a="open">${x.mine?'STAFF (@'+esc(x.user)+')':'Consulter'}</button>
      ${x.status==='open'&&r>=2?`<button class="lite green" data-a="claim">Réclamer</button>${x.student_pending?`<button class="lite orange" data-a="claimS">Réclamer avec l’Administrateur Élève @${esc(x.student)}</button>`:''}`:''}
      ${x.status==='open'&&r===1&&!x.student?'<button class="lite orange" data-a="req">Demander à réclamer avec un administrateur</button>':''}${x.req_mine?'<span class="tag">demande envoyée</span>':''}</div></div>`).join('')||'<p class="muted">Aucune demande.</p>');
    SYS.staffOpen=L.filter(x=>x.status==='open').length};
  await draw();
  box.onclick=async e=>{const a=e.target.dataset&&e.target.dataset.a;if(!a)return;const ref=e.target.closest('[data-r]').dataset.r;
    try{if(a==='open'){const L=await rpcd('support_list');const x=L.find(y=>y.ref===ref);if(x&&x.mine&&x.conv){m.close();return openTicketConv(x.conv)}return ticketPeek(ref)}
      if(a==='req')await rpcd('support_student_req',{p_ref:ref});else{await rpcd('support_claim',{p_ref:ref,p_with_student:a==='claimS'});await loadConvs();renderList()}
      toast('Fait');draw()}catch(x){toast(errMsg(x));draw()}};
}
async function stAnnonces(m,box){
  box.innerHTML=`<p class="muted">Message envoyé dans @system. Laissez la liste vide pour écrire à tout le monde.</p><input id="anU" placeholder="@personne1 @personne2 (vide = tous)"><textarea id="anB" rows="6" placeholder="Message (sans limite pratique)" style="margin-top:6px"></textarea><div class="row end"><button id="anGo">Envoyer</button></div>
    ${RK()>=4?`<label>Comptes officiels (connexion par code)</label><div class="row"><button class="ghost lite" data-k="system">Générer un code @system</button><button class="ghost lite" data-k="staff">Générer un code @staff</button></div><div class="row"><button class="ghost lite" data-rv="system">Révoquer @system</button><button class="ghost lite" data-rv="staff">Révoquer @staff</button></div><p class="muted">Le code s’affiche une seule fois. Connexion : nom d’utilisateur system ou staff, et le code comme mot de passe.</p>`:''}`;
  box.onclick=async e=>{const t=e.target;try{
    if(t.id==='anGo'){const us=$('#anU',box).value.split(/[\s,]+/).filter(Boolean);const n=await rpcd('world_post',{p_users:us.length?us:null,p_body:$('#anB',box).value});toast(n<0?'Annonce envoyée à tous':n+' destinataire(s)');$('#anB',box).value=''}
    else if(t.dataset.k){if(!confirm('Générer un nouveau code pour @'+t.dataset.k+' ? L’ancien cesse de fonctionner.'))return;const c=await rpcd('acct_code_make',{p_name:t.dataset.k});const mm=modal(`<h3>Code de @${esc(t.dataset.k)}</h3><p class="muted">Copiez-le maintenant : il ne sera plus affichable. <b>Valable 5 minutes</b>, puis il ne permet plus de se connecter.</p><textarea readonly rows="3" style="font-family:monospace">${esc(c)}</textarea><div class="row end"><button id="cdCp">Copier</button><button class="ghost" data-x>Fermer</button></div>`,true);$('#cdCp',mm).onclick=()=>{navigator.clipboard.writeText(c).then(()=>toast('Copié'),()=>{})}}
    else if(t.dataset.rv){if(!confirm('Révoquer la connexion de @'+t.dataset.rv+' ?'))return;await rpcd('acct_code_clear',{p_name:t.dataset.rv});toast('Code révoqué')}
  }catch(x){toast(errMsg(x))}};
}
