const RIGHTS=[['send_messages','Envoyer des messages'],['upload_files','Importer des fichiers'],['mention','Mentionner'],['call','Appels'],['start_game','Lancer un jeu'],['play','Jouer'],['import_game','Importer un jeu (Libon)'],['create_groups','Créer des groupes'],['add_members','Ajouter quelqu’un ou des bots'],['edit_conv','Modifier la conversation'],['customize_group','Personnaliser le groupe'],['become_admin','Devenir administrateur'],['friend_requests','Demandes d’amis'],['edit_profile','Modifier le profil'],['create_bot','Créer un bot'],['bot_cmds','Commandes de bot'],['quests','Quêtes'],['shop_buy','Acheter à la boutique'],['buy_tokens','Acheter des jetons'],['referral','Parrainer'],['rmn_import','Romanomoney (import, échange)'],['transfer','Transférer'],['promo_codes','Codes promo'],['export','Exporter'],['tournaments','Tournois'],['esport','Équipe e-Sport'],['anon_suggest','Boîte à suggestions anonyme'],['vote','Voter'],['nickname','Surnoms dans le groupe']];
const RN=Object.fromEntries(RIGHTS);
async function rightsPanel(box,conv,fixedUser){
  box.innerHTML=`<div class="row"><input id="rgU" class="grow" placeholder="@utilisateur" ${fixedUser?'value="@'+esc(fixedUser)+'" readonly':''}><button class="ghost lite" id="rgL">Voir</button></div>
    <div class="row" style="flex-wrap:wrap"><select id="rgK">${RIGHTS.map(r=>`<option value="${r[0]}">${esc(r[1])}</option>`).join('')}</select>
    ${conv?'':'<select id="rgS"><option value="">Tout le site</option><option value="c">Une conversation (numéro)</option></select><input id="rgC" placeholder="C-000123" style="width:110px;display:none">'}
    <input id="rgT" type="number" min="0" placeholder="Durée (s), vide = illimitée" style="width:190px"><input id="rgR" class="grow" placeholder="Raison"></div>
    <div class="row end"><button class="lite" id="rgOff">Retirer</button></div><div id="rgO"></div>`;
  const cn=()=>conv||(($('#rgS',box)&&$('#rgS',box).value==='c')?+($('#rgC',box).value.replace(/\D/g,'')||0):null);
  const sc=$('#rgS',box);if(sc)sc.onchange=()=>{$('#rgC',box).style.display=sc.value==='c'?'':'none'};
  const list=async()=>{try{const d=await rpcd('rights_list',{p_username:$('#rgU',box).value,p_conv_num:conv||null});
    $('#rgO',box).innerHTML=d.length?d.map(x=>`<div class="cas-row"><b>${esc(RN[x.right]||x.right)} · ${x.conv?'conversation '+esc(trk(x.conv)):'tout le site'}</b>${esc(x.reason)}<br><span class="muted">par @${esc(x.by||'?')} · ${x.until?'jusqu’au '+esc(fmtDt(x.until)):'illimité'}</span><br><button class="ghost lite" data-r="${esc(x.right)}" data-c="${x.conv||''}">Rétablir</button></div>`).join(''):'<p class="muted">Aucun droit retiré.</p>'}catch(e){toast(errMsg(e))}};
  $('#rgL',box).onclick=list;
  $('#rgOff',box).onclick=async()=>{try{const t=$('#rgT',box).value;await rpcd('right_set',{p_username:$('#rgU',box).value,p_right:$('#rgK',box).value,p_conv_num:cn(),p_allowed:false,p_reason:$('#rgR',box).value,p_secs:t?+t:null});toast('Droit retiré');list()}catch(e){toast(errMsg(e))}};
  box.addEventListener('click',async e=>{const d=e.target.dataset;if(!d||!d.r)return;try{await rpcd('right_set',{p_username:$('#rgU',box).value,p_right:d.r,p_conv_num:d.c?+d.c:null,p_allowed:true,p_reason:null,p_secs:null});toast('Droit rétabli');list()}catch(x){toast(errMsg(x))}});
}
async function stRights(m,box){rightsPanel(box,null)}
async function stConvs(m,box){
  box.innerHTML=`<p class="muted">Liste des conversations (nom, numéro, type). Les messages ne sont pas accessibles ici.</p><div class="row"><input id="cvQ" class="grow" placeholder="Nom, @membre ou numéro"><button class="ghost lite" id="cvGo">Chercher</button></div><div id="cvO"></div>`;
  const go=async()=>{try{const d=await rpcd('conv_list',{p_q:$('#cvQ',box).value});$('#cvO',box).innerHTML=d.map(x=>`<div class="shrow2"><div class="grow"><b>${esc(trk(x.num))} · ${esc(x.name||'Sans nom')}</b><small>${x.kind==='group'?'Groupe':'Discussion'} · ${x.mode==='e2e'?'chiffrée':'claire'} · ${x.members} membre(s)</small></div></div>`).join('')||'<p class="muted">Aucun résultat.</p>'}catch(e){toast(errMsg(e))}};
  $('#cvGo',box).onclick=go;go();
}
async function viewAttachment(ref){
  let url;try{url=/^https?:/.test(ref)?ref:isPriv(ref)?await signedUrl(ref):pubUrl(ref)}catch(e){return toast('Média indisponible')}
  const audio=/\.(webm|ogg|mp3|m4a|wav)(\?|$)/i.test(url);
  const m=modal(audio?`<audio controls autoplay src="${esc(url)}" style="width:100%"></audio>`:`<img class="lbimg" src="${esc(url)}" alt="" style="max-width:100%">`,true);
  m.firstChild.style.padding='8px';m.firstChild.style.maxWidth='96vw';
}
async function stReports(m,box){
  const open=await rpcd('report_list',{p_status:'open'});
  box.innerHTML=`<p class="muted">Signalements ouverts (${open.length})</p>${open.map(r=>`<div class="cas-row" data-ref="${esc(r.ref)}"><b>${esc(r.ref)} · ${r.kind==='group'?'Groupe':'Message'} · ${esc(trk(r.conv||0))} ${esc(r.conv_name||'')}</b>Par @${esc(r.by||'?')}${r.target?' contre @'+esc(r.target):''} : ${esc(r.reason)}
    ${(r.snapshot||[]).map(s=>`<div class="muted" style="margin-left:8px">@${esc(s.from||'?')} : ${esc(String(s.text||'').slice(0,300))}${s.url?` <a href="#" data-img="${esc(s.url)}">voir</a>`:''}</div>`).join('')}
    <div class="row" style="flex-wrap:wrap;margin-top:6px"><button class="ghost lite" data-a="view">Voir la conversation</button><input class="rpT" placeholder="@personne" style="width:120px"><input class="rpS" type="number" min="0" placeholder="Durée (s)" style="width:90px"><button class="ghost lite" data-a="mute">Rendre muet</button><button class="ghost lite" data-a="kick">Bannir du groupe</button><button class="ghost lite" data-a="demote">Retirer modérateur</button><button class="ghost lite" data-a="purge_user">Supprimer ses messages</button><button class="ghost lite" data-a="remove_bots">Retirer les bots</button><button class="lite" data-a="close">Clore</button></div><div class="rpO"></div></div>`).join('')}`;
  box.onclick=async e=>{const im=e.target.closest&&e.target.closest('[data-img]');if(im){e.preventDefault();return viewAttachment(im.dataset.img)}const a=e.target.dataset&&e.target.dataset.a;if(!a)return;const card=e.target.closest('[data-ref]'),ref=card.dataset.ref,tg=card.querySelector('.rpT').value.trim()||null,sc=card.querySelector('.rpS').value;
    try{
      if(a==='view'){const d=await rpcd('report_conv_view',{p_ref:ref});card.querySelector('.rpO').innerHTML='<div style="max-height:220px;overflow:auto;margin-top:6px">'+d.map(x=>`<div><span class="muted">#${x.n} @${esc(x.from)}</span> ${x.media?`<a href="#" data-img="${esc(x.media)}">[${esc(x.kind==='voice'?'message vocal':'image')} : voir]</a>`:/^https:/.test(x.body||'')&&x.kind!=='text'?`<a href="#" data-img="${esc(x.body)}">[GIF : voir]</a>`:x.body==null?'['+esc(x.kind)+']':esc(x.body)} <button class="ghost lite" data-a="del" data-n="${x.n}">Supprimer</button></div>`).join('')+'</div>';return}
      if(a==='del'){await rpcd('report_action',{p_ref:ref,p_action:'delete_msgs',p_msgs:[+e.target.dataset.n]});e.target.parentNode.remove();toast('Message supprimé');return}
      if(a==='close'){const n=prompt('Note de clôture');if(n==null)return;await rpcd('report_close',{p_ref:ref,p_note:n});toast('Signalement clos');return stReports(m,box)}
      if(a==='purge_user'&&!confirm('Supprimer tous les messages de cette personne dans la conversation ?'))return;
      await rpcd('report_action',{p_ref:ref,p_action:a,p_target:tg,p_secs:sc?+sc:null});toast('Fait');
    }catch(x){toast(errMsg(x))}};
}
function reportModal(c,msgId){
  const desc=x=>{const d=x._d||{};if(d.k==='video')return '[vidéo]';if(d.k==='image'||d.k==='drawing')return '[image]';if(d.k==='voice')return '[message vocal]';if(d.u)return '[GIF]';if(d.k==='game')return '[résultat de jeu]';return String(d.t||'')};
  const snapOf=x=>{const p=S.profiles.get(x.sender_id),d=x._d||{};const o={id:x.id,from:(p&&p.username)||'?',text:desc(x).slice(0,2000),at:x.created_at};
    if(c.mode==='clear'&&d.p&&['image','drawing','voice'].includes(d.k))o.url=isPriv(d.p)?d.p:pubUrl(d.p);else if(d.u)o.url=d.u;return o};
  let all=(S.msgs[c.id]||[]).filter(x=>x.kind!=='system'&&x._d);
  const m=modal(`<h3>Signaler</h3><p class="muted">Le signalement est envoyé aux chefs des administrateurs. Cochez des messages précis, ou ne cochez rien pour envoyer toute la conversation.</p>
    <label>Raison</label><textarea id="rpR" rows="3" maxlength="500" style="width:100%;min-height:70px"></textarea><label>Personne concernée (facultatif)</label><input id="rpT" placeholder="@utilisateur" style="width:100%">
    <label>Messages joints <span class="muted" id="rpN"></span></label><div class="row" style="gap:6px"><button class="ghost lite" id="rpOld">Charger les messages plus anciens</button><button class="ghost lite" id="rpNone">Tout décocher</button></div>
    <div id="rpL" style="max-height:240px;overflow:auto;margin-top:6px"></div>
    <div class="row end"><button class="ghost" data-x>Annuler</button><button id="rpGo">Envoyer</button></div>`,true);
  const draw=()=>{const keep=new Set([...m.querySelectorAll('[data-m]:checked')].map(i=>+i.dataset.m));if(!keep.size&&msgId&&!m._init){keep.add(msgId);m._init=1}
    $('#rpL',m).innerHTML=all.map(x=>{const p=S.profiles.get(x.sender_id);return `<label class="row" style="margin:2px 0;color:var(--text)"><input type="checkbox" data-m="${x.id}" ${keep.has(x.id)?'checked':''}> <span class="grow"><b>@${esc((p&&p.username)||'?')}</b> <span class="muted">${esc(new Date(x.created_at).toLocaleString('fr-CA'))}</span> ${esc(desc(x).slice(0,200))}</span></label>`}).join('')||'<p class="muted">Aucun message.</p>';
    $('#rpN',m).textContent='('+all.length+' chargés)'};
  draw();
  $('#rpNone',m).onclick=()=>{m.querySelectorAll('[data-m]').forEach(i=>i.checked=false)};
  $('#rpOld',m).onclick=async e=>{e.target.disabled=true;try{
      for(let k=0;k<25;k++){const first=all[0];if(!first)break;const {data}=await sb.from('messages').select('*').eq('conversation_id',c.id).lt('id',first.id).order('id',{ascending:false}).limit(100);
        const rows=(data||[]).reverse();if(!rows.length)break;await Promise.all(rows.map(r=>decode(c,r)));all=rows.filter(r=>r.kind!=='system'&&r._d).concat(all);if(rows.length<100)break}
      draw();toast('Historique chargé')}catch(x){toast(errMsg(x))}e.target.disabled=false};
  $('#rpGo',m).onclick=async e=>{
    const sel=new Set([...m.querySelectorAll('[data-m]:checked')].map(i=>+i.dataset.m));const arr=sel.size?all.filter(x=>sel.has(x.id)):all;
    const snap=arr.slice(-2000).map(snapOf);
    e.target.disabled=true;try{const ref=await rpcd('report_create',{p_conv:c.id,p_kind:sel.size===1&&snap.length===1?'message':'group',p_target:$('#rpT',m).value.trim()||null,p_reason:$('#rpR',m).value.trim(),p_snapshot:snap});m.close();toast('Signalement '+ref+' envoyé ('+snap.length+' message'+(snap.length>1?'s':'')+')')}catch(x){e.target.disabled=false;toast(errMsg(x))}};
}
document.addEventListener('contextmenu',e=>{
  const row=e.target.closest&&e.target.closest('#msgs .mrow[data-mid]');if(!row||e.defaultPrevented)return;const c=cur();if(!c)return;
  e.preventDefault();document.querySelectorAll('.ctxm').forEach(x=>x.remove());
  const m=document.createElement('div');m.className='ctxm';m.style.left=Math.min(e.clientX,innerWidth-200)+'px';m.style.top=Math.min(e.clientY,innerHeight-60)+'px';
  m.innerHTML='<button>Signaler ce message</button>';document.body.appendChild(m);
  const close=()=>{m.remove();document.removeEventListener('mousedown',away,true)};const away=ev=>{if(!m.contains(ev.target))close()};setTimeout(()=>document.addEventListener('mousedown',away,true),0);
  m.querySelector('button').onclick=()=>{close();reportModal(c,+row.dataset.mid)};
});
