devStaff=async function(){
  const r=RK();
  const tabs=[['p','Progression',1],['d','Détections Ciffron',1],['b','Bots',2],['j','Journaux',1],['u','Bannissements',2],['q','Support',1],['a','Annonces',3],['s','Sanctions',2],['o','Droits',3],['v','Conversations',2],['g','Signalements',3],['k','Jetons',2],['i','Adresses IP',3],['e','Exceptions Ciffron',3],['r','Demandes',3],['t','Équipe',3],['f','Contrôle',4],['m','Courriels',3],['c','Cadres',4],['y','Équipes e-Sport',2],['z','Badges',4],['w','Espace',4],['l','Légal',4]].filter(t=>r>=t[2]);
  const m=modal(`<h3>Administration <span class="rbadge r-${esc(S.staff)}">${esc(ROLES[S.staff]||'')}</span></h3><div class="row" id="stT" style="flex-wrap:wrap">${tabs.map(t=>`<button class="ghost lite" data-t="${t[0]}">${t[1]}</button>`).join('')}</div><div id="stC" class="devtab"></div><div class="row end"><button class="ghost" data-x>Fermer</button></div>`,true);
  m.classList.add('devmodal');
  const T={f:stAudit,m:stMails,c:stFrames,p:stProgress,d:stDetections,b:stBots,u:stBans,s:stSanc,q:stSupport,a:stAnnonces,o:stRights,v:stConvs,g:stReports,e:stExc,j:stLogs,k:stTokens,i:stIps,r:stReqs,t:stTeam,y:stEsp,z:stBdg,w:stSpace,l:stLegal};
  const show=async t=>{$$('#stT [data-t]',m).forEach(b=>b.classList.toggle('on',b.dataset.t===t));const c=$('#stC',m);c.innerHTML='<p class="muted">Chargement…</p>';try{await T[t](m,c)}catch(e){c.innerHTML='<p class="muted">'+esc(errMsg(e))+'</p>'}};
  $('#stT',m).onclick=e=>{const t=e.target.dataset&&e.target.dataset.t;if(t)show(t)};
  m._show=show;show('p');
};
stSource=async function(bot,flagged){
  const r=RK();let j=null;
  if(r>=2||!flagged){j=prompt('Justification (15 caractères minimum, journalisée)');if(!j)return}
  const {data,error}=await sb.rpc('staff_bot_source',{p_bot:bot,p_justification:j});if(error)return toast(error.message);
  const prot=new Set((data.protected||[]).map(x=>x.hash));
  const m=modal(`<h3>${esc(data.bot)} — ${data.window?'lignes signalées':'répertoire'}</h3>${data.window?'<p class="muted">Seules les 6 lignes avant et après chaque ligne signalée sont visibles.</p>':''}${(data.files||[]).map(f=>`<div class="dev-srcf"><b>${esc(f.path)}</b> <span class="muted">${fmtSz(f.size)}</span>${f.content===null?'<div class="muted">binaire</div>':`<div class="dev-src">${f.content.split(/\r?\n/).map((l,i)=>{if(data.window&&l==='')return '';const p=prot.has(Ciffron.lineHash(f.path,l));const bad=Ciffron.blocking(Ciffron.scanFile(f.path,l,prot)).length;return `<div class="${p?'pl-prot':bad?'pl-bad':''}" ${p?'title="protégé"':''}><i>${i+1}</i>${esc(l)||' '}</div>`}).join('')}</div>`}</div>`).join('')}<div class="row end"><button class="ghost" data-x>Fermer</button></div>`,true);
  m.classList.add('devmodal');
};
