document.addEventListener('contextmenu',e=>{
  const it=e.target.closest&&e.target.closest('#list .item[data-id]');if(!it)return;
  e.preventDefault();document.querySelectorAll('.ctxm').forEach(x=>x.remove());
  const id=it.dataset.id,on=TK.pins.has(id);
  const m=document.createElement('div');m.className='ctxm';m.style.left=Math.min(e.clientX,innerWidth-200)+'px';m.style.top=Math.min(e.clientY,innerHeight-60)+'px';
  m.innerHTML=`<button>${on?'Retirer l’épingle':'Épingler en haut'}</button>`;document.body.appendChild(m);
  const close=()=>{m.remove();document.removeEventListener('mousedown',away,true)};const away=ev=>{if(!m.contains(ev.target))close()};setTimeout(()=>document.addEventListener('mousedown',away,true),0);
  m.querySelector('button').onclick=async()=>{close();
    try{await rpcd('pin_set',{p_conv:id,p_on:!on});await pinsLoad();renderList()}
    catch(x){toast(errMsg(x));if(/Achetez/.test(errMsg(x)))balOpen('s')}};
});

/* ---------- emojis premium (onglet du sélecteur) ---------- */
async function peLoad(){
  try{if(!TK.pe)TK.pe=await rpcd('emoji_premium_list');TK.peOwn=!!(await rpcd('has_item',{p_code:'pack_emoji'}))}catch(e){TK.pe=TK.pe||{}}
}
const PESET=()=>{const s=new Set();Object.values(TK.pe||{}).forEach(a=>a.forEach(x=>s.add(x)));return s};
EMOJIS.Premium='';
const _rpT=renderPicker;
renderPicker=function(cat){
  _rpT.apply(this,arguments);
  if(cat!=='Premium')return;
  const g=$('#picker .pg');if(!g)return;const pe=TK.pe||{},cats=Object.keys(pe);
  const cur=TK.peCat&&pe[TK.peCat]?TK.peCat:cats[0];
  g.innerHTML=`<div class="pe-sub">${cats.map(c=>`<button class="${c===cur?'':'ghost'}" data-pc="${esc(c)}">${esc(c)}</button>`).join('')}</div>`+(pe[cur]||[]).map(e=>`<button data-e="${e}" data-pe="1"><span class="emo a${e.codePointAt(0)%6}">${e}</span></button>`).join('')+(TK.peOwn?'':'<div class="muted" style="grid-column:1/-1;font-size:11px;margin-top:4px">Réservé aux abonnés du pack premium</div>');
};
document.addEventListener('click',e=>{
  const pc=e.target.closest&&e.target.closest('#picker [data-pc]');if(pc){e.stopImmediatePropagation();TK.peCat=pc.dataset.pc;renderPicker('Premium');return}
  const b=e.target.closest&&e.target.closest('#picker [data-pe]');
  if(b&&!TK.peOwn){e.stopImmediatePropagation();e.preventDefault();toast('Réservé aux abonnés du pack premium');balOpen('s')}
},true);
const _spT=sendPayload;
sendPayload=function(c,p){
  if(p&&p.k==='text'&&!TK.peOwn&&TK.pe){const s=PESET();for(const ch of String(p.t||'')){if(s.has(ch)){toast('Réservé aux abonnés du pack premium');balOpen('s');return Promise.reject(new Error('Emoji réservé aux abonnés'))}}}
  return _spT.apply(this,arguments);
};

/* ---------- réglages : jetons, signalement de bogue, crédits ---------- */
const _dsT=devSettings;
devSettings=function(m){
  _dsT.apply(this,arguments);
  const cr=m.querySelector('.credits');if(!cr||m.querySelector('#sShop'))return;
  const d=document.createElement('div');d.className='devsec';d.innerHTML=`<label>Jetons</label><div class="row"><span class="grow">Solde, boutique, quêtes, parrainage</span><button class="ghost" id="sShop">Ouvrir</button></div><div class="row" style="margin-top:6px"><span class="grow">Un problème sur le site ?</span><button class="ghost" id="sBug">Signaler un bogue</button></div>`;
  cr.before(d);$('#sShop',m).onclick=()=>{m.close();balOpen()};$('#sBug',m).onclick=()=>{m.close();bugOpen()};
  sb.rpc('credits_list').then(r=>{if(r&&r.data&&r.data.length&&cr.isConnected)cr.insertAdjacentHTML('beforeend',r.data.map(n=>`<div class="cr-l"><span>${esc(n)}</span><b>Soutien</b></div>`).join(''))},()=>{});
};
function bugOpen(){
  const m=modal(`<h3>Signaler un bogue</h3><p class="muted">Un bogue approuvé par un administrateur rapporte 55 jetons.</p><label>Titre</label><input id="bgT" maxlength="120"><label>Description (étapes pour le reproduire)</label><textarea id="bgB" rows="6" maxlength="4000" style="width:100%"></textarea><div class="row end"><button class="ghost" data-x>Annuler</button><button id="bgGo">Envoyer</button></div>`);
  $('#bgGo',m).onclick=async e=>{e.target.disabled=true;try{await rpcd('bug_report',{p_title:$('#bgT',m).value,p_body:$('#bgB',m).value});toast('Signalement envoyé');m.close()}catch(x){e.target.disabled=false;toast(errMsg(x))}};
}

/* ---------- parrainage : page d'invitation (visiteur) et lien ouvert par un membre ---------- */
const REF={code:null,old:false,active:false,token:null,info:null};
const refOld=()=>{try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(/^sb-/.test(k)||/^cm_/.test(k))return true}}catch(e){}return false};
function refCache(){
  const o={ua:navigator.userAgent,lang:navigator.language,tz:(Intl.DateTimeFormat().resolvedOptions()||{}).timeZone||'',screen:[screen.width,screen.height],at:new Date().toISOString(),ls:{},ss:{},cookies:'',idb:[]};
  const mask=(k,v)=>/auth-token|access|refresh/i.test(k)?'(jeton masqué, '+String(v).length+' caractères)':String(v).slice(0,2000);
  try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);o.ls[k]=mask(k,localStorage.getItem(k))}}catch(e){}
  try{for(let i=0;i<sessionStorage.length;i++){const k=sessionStorage.key(i);o.ss[k]=mask(k,sessionStorage.getItem(k))}}catch(e){}
  try{o.cookies=document.cookie.split(';').map(c=>{const p=c.split('=');return p[0].trim()+'='+mask(p[0],p.slice(1).join('='))}).join('; ')}catch(e){}
  return o;
}
async function refCacheFull(){const o=refCache();try{if(indexedDB.databases)o.idb=((await indexedDB.databases())||[]).map(d=>d.name)}catch(e){}return o}
function refContestModal(after){
  const m=modal(`<h3>Contester</h3><p class="muted">Si c’est vraiment votre premier compte, expliquez-le. Le contenu complet du cache de ce navigateur (sans vos jetons de connexion) est transmis à un administrateur avec votre raison. Vous devez quand même créer votre compte : les récompenses sont versées si la contestation est acceptée.</p><label>Raison</label><textarea id="rcR" rows="5" maxlength="1500" style="width:100%"></textarea><div class="row end"><button class="ghost" data-x>Annuler</button><button id="rcGo">Envoyer la contestation</button></div>`);
  $('#rcGo',m).onclick=async e=>{
    const reason=$('#rcR',m).value.trim();if(reason.length<5)return toast('Expliquez la raison');e.target.disabled=true;
    try{await after(reason,await refCacheFull());m.close()}catch(x){e.target.disabled=false;toast(errMsg(x))}};
}
async function refLanding(cd){
  const card=document.querySelector('#auth .card');if(!card||document.getElementById('refBanner'))return;
  if(!/^[a-zA-Z0-9]{5}$/.test(cd||'')){S.pendingGo=null;return toast('Lien de parrainage invalide')}
  REF.active=true;REF.code=cd;REF.old=refOld();
  let info=null;try{const r=await sb.rpc('referral_preview',{p_code:cd});info=r.data&&r.data.ok?r.data:null}catch(e){}
  REF.info=info;if(!info)REF.code=null;
  const ban=document.createElement('div');ban.id='refBanner';
  const who=info?esc(info.nickname?info.nickname+' (@'+info.username+')':'@'+info.username):'';
  ban.innerHTML=(REF.old?`<div class="refbox warn" id="refWarn"><b>Aucune récompense possible.</b> Cet appareil s’est déjà connecté à Communicer! : ni vous ni votre parrain ne recevrez de jetons. Vous pouvez quand même créer un compte.<div class="row" style="margin-top:6px"><button class="ghost lite" id="refCt">Contester</button></div></div>`:'')
    +(info?`<div class="refbox"><b>Invitation de ${who}</b><ul><li>Vous serez automatiquement amis avec ${who} à l’inscription.</li>${REF.old?`<li><s>${who} recevra ${nfmt(info.referrer)} jetons</s></li><li><s>Vous recevrez ${nfmt(info.referred)} jetons</s></li>`:`<li>${who} recevra <b>${nfmt(info.referrer)} jetons</b>.</li><li>Vous recevrez <b>${nfmt(info.referred)} jetons</b>.</li>`}</ul></div>`:'<div class="refbox err">Ce code de parrainage n’existe pas. Vous pouvez quand même créer un compte.</div>');
  card.prepend(ban);
  const ti=$('#tabIn');if(ti)ti.style.display='none';
  const ct=$('#refCt');if(ct)ct.onclick=()=>refContestModal(async(reason,cache)=>{REF.token=Array.from(crypto.getRandomValues(new Uint8Array(20)),b=>b.toString(16).padStart(2,'0')).join('');
    const r=await sb.rpc('referral_contest_anon',{p_code:REF.code,p_token:REF.token,p_reason:reason,p_cache:cache});if(r.error){REF.token=null;throw r.error}
    ct.disabled=true;$('#refWarn').insertAdjacentHTML('beforeend','<p><b>Contestation envoyée.</b> Créez votre compte : les jetons seront versés si elle est acceptée.</p>')});
  setAuthMode('up');
}
const _saT=showAuth;
showAuth=function(msg){_saT.apply(this,arguments);const g=S.pendingGo;if(g&&g.go==='ref')refLanding(g.cd)};
const _samT=setAuthMode;
setAuthMode=function(m){if(REF.active)m='up';return _samT.call(this,m)};
const _suT=signUp;
signUp=async function(){
  await _suT.apply(this,arguments);
  try{localStorage.setItem('cm_seen','1')}catch(e){}
  if(REF.active&&REF.code){
    try{const r=await sb.rpc('referral_claim',{p_code:REF.code,p_clean:!REF.old,p_token:REF.token});S.refResult=r.data||{status:'error',message:r.error&&r.error.message}}catch(e){S.refResult={status:'error'}}
    S.pendingGo=null;REF.active=false;
  }
};
function refResultShow(){
  const r=S.refResult;if(!r)return;S.refResult=null;
  const who=r.referrer?'@'+esc(r.referrer):'votre parrain';
  if(r.status==='rewarded')return modal(`<h3>Bienvenue</h3><p>Vous êtes maintenant ami avec ${who}. Vous avez reçu <b>${nfmt(r.gain||125)} jetons</b>.</p><div class="row end"><button data-x>Continuer</button></div>`);
  if(r.status==='contest_pending')return modal(`<h3>Contestation en attente</h3><p>Vous êtes ami avec ${who}. Les jetons seront versés à la décision d’un administrateur, si elle est favorable.</p><div class="row end"><button data-x>Continuer</button></div>`);
  if(r.status==='no_reward'){const why={old_cache:'cet appareil s’était déjà connecté à Communicer!',shared_ip:'un autre compte utilise la même connexion',cap:'ce parrain a atteint sa limite du jour'}[r.reason]||'les conditions ne sont pas remplies';
    const m=modal(`<h3>Aucune récompense</h3><p>Vous êtes ami avec ${who}, mais aucun jeton n’est versé : ${why}.</p><div class="row end"><button class="ghost" id="rrCt">Contester</button><button data-x>Continuer</button></div>`);
    const b=$('#rrCt',m);if(r.reason==='cap')b.remove();else b.onclick=()=>{m.close();refContestModal(async(reason,cache)=>{await rpcd('referral_contest_me',{p_reason:reason,p_cache:cache});toast('Contestation envoyée')})}}
}
async function goRef(cd){
  /* membre déjà connecté qui ouvre un lien de parrainage : aucune récompense possible */
  const m=modal(`<h3>Lien de parrainage</h3><div class="refbox warn"><b>Aucune récompense possible :</b> vous êtes déjà connecté. Un lien de parrainage ne sert qu’à créer un nouveau compte.</div><p class="muted">Pour inviter quelqu’un, partagez votre propre lien (fenêtre des jetons, onglet Parrainage).</p><div class="row end"><button class="ghost" data-x>Fermer</button><button id="grMy">Mon lien</button></div>`);
  $('#grMy',m).onclick=()=>{m.close();balOpen('r')};
}

/* ---------- événements de quêtes et victoires ---------- */
const _sclT=startCallLive;startCallLive=function(){try{sb.rpc('quest_event',{p_kind:'call'}).then(()=>{},()=>{})}catch(e){}return _sclT.apply(this,arguments)};
const _ssT=startSession;startSession=function(){try{sb.rpc('quest_event',{p_kind:'game'}).then(()=>{},()=>{})}catch(e){}return _ssT.apply(this,arguments)};
function winRecord(ss){
  try{if(EV.convs.has(ss.conv)&&ss.players.length===2){const o=gameOutcome(ss.game,ss.state,S.me.id);if(o&&typeof o.won==='boolean'){const w=o.won?S.me.id:ss.players.find(u=>u!==S.me.id);const pw=S.profiles.get(w);
    if(pw)rpcd('ev_report',{p_conv:ss.conv,p_winner:pw.username}).then(r=>{if(r==='done')toast('Résultat du match enregistré');else if(r==='disputed')toast('Résultats contradictoires : l’organisateur tranchera')},()=>{})}}}catch(e){}
  try{const c=S.convs.get(ss.conv);if(!c||c.kind!=='group')return;const o=gameOutcome(ss.game,ss.state,S.me.id);if(!o||o.won!==true)return;
    sb.rpc('game_win',{p_conv:ss.conv,p_game:ss.game,p_session:ss.id}).then(r=>{if(r&&r.data>0){toast('+'+r.data+' jeton (victoire en groupe)');balRefresh()}},()=>{})}catch(e){}
}

/* ---------- administration : jetons, badges, bogues, contestations, demandes ---------- */
async function stTokens(m,box){
  const sh=await rpcd('shop_list');const items=sh.items.filter(i=>i.kind!=='credit');
  const allB=['nouveau_venu','habitue','veteran','aine','champion','chasseur','ambassadeur','strategie','elite','premier','ingenieur','gardien','developpeur','concepteur','fondateur','aristocrate','cybernaute','enigmatique','legende','souverain','grand_mecene','mecene','legende_mecene'];
  const BN={nouveau_venu:'Nouveau venu',habitue:'Habitué',veteran:'Vétéran',aine:'Aîné',champion:'Champion',chasseur:'Chasseur de bogue',ambassadeur:'Ambassadeur',strategie:'Stratège',elite:'Élite',premier:'Premier',ingenieur:'Ingénieur',gardien:'Gardien',developpeur:'Développeur',concepteur:'Concepteur',fondateur:'Fondateur',aristocrate:'Aristocrate',cybernaute:'Cybernaute',enigmatique:'Énigmatique',legende:'Légende',souverain:'Souverain',grand_mecene:'Grand mécène',mecene:'Mécène',legende_mecene:'Légende du mécène'};
  box.innerHTML=`<div class="row" id="tkT" style="flex-wrap:wrap"><button class="ghost lite on" data-s="w">Jetons et badges</button><button class="ghost lite" data-s="b">Bogues</button><button class="ghost lite" data-s="c">Contestations</button><button class="ghost lite" data-s="d">Demandes de badge</button>${RK()>=4?'<button class="ghost lite" data-s="p">Paiements et promos</button>':''}</div><div id="tkC"></div>`;
  const C=$('#tkC',box);
  const views={
    p:async()=>{const L=await rpcd('promo_list');const pk=await rpcd('pack_list');
      C.innerHTML=`<label>Créer un code promo</label><div class="row" style="flex-wrap:wrap"><input id="pcC" placeholder="CODE" maxlength="24" style="width:130px"><input id="pcP" type="number" min="1" max="100" placeholder="% (1-100)" style="width:100px"><input id="pcM" type="number" min="1" placeholder="Utilisations max (vide = infini)" style="width:230px"><input id="pcU1" type="number" min="1" placeholder="Par personne (vide = infini)" style="width:220px"></div>
        <div class="row" style="flex-wrap:wrap;margin-top:6px"><label class="muted grow">Début <input id="pcF" type="datetime-local"></label><label class="muted grow">Fin <input id="pcE" type="datetime-local"></label></div>
        <div class="row" style="flex-wrap:wrap;margin-top:6px"><input id="pcB" placeholder="Badge requis (code, facultatif)" style="width:240px"><label class="muted"><input type="checkbox" id="pcPu"> Réservé aux personnes ayant déjà acheté</label></div>
        <div class="row" style="flex-wrap:wrap;margin-top:6px"><label class="muted"><input type="checkbox" id="pcAll" checked> Tous les packs</label>${pk.map(k=>`<label class="muted"><input type="checkbox" class="pcI" value="${esc(k.code)}"> ${k.medals?nfmt(k.medals)+' coq.':nfmt(k.tokens)}</label>`).join('')}<button class="ghost lite" id="pcGo">Créer</button></div>
        <label>Codes</label>${L.map(c=>`<div class="shrow2"><div class="grow"><b>${esc(c.code)}</b> −${c.pct} %<small>${c.items.includes('*')?'tous les packs':c.items.map(x=>esc((pk.find(k=>k.code===x)||{}).tokens||x)).join(', ')} · ${c.uses} / ${c.max==null?'∞':c.max} utilisations${c.per_user?' · '+c.per_user+' par personne':''}${c.from?' · dès '+esc(fmtDt(c.from)):''}${c.until?' · jusqu’au '+esc(fmtDt(c.until)):''}${c.badge?' · badge '+esc(c.badge):''}${c.purchase?' · acheteurs':''}${c.active?'':' · désactivé'}</small></div><button class="ghost lite" data-t="${esc(c.code)}" data-a="${c.active?0:1}">${c.active?'Désactiver':'Activer'}</button></div>`).join('')||'<p class="muted">Aucun code.</p>'}
        <label>Journaux conservés (50 à 500 lignes ; les plus anciennes sont supprimées)</label><div class="row"><input id="lkN" type="number" min="50" max="500" class="grow" style="max-width:120px"><button class="ghost lite" id="lkS">Appliquer</button><button class="ghost lite" id="lkA">Voir les alertes</button></div>
        <label class="muted" style="display:flex;gap:8px;align-items:center;margin-top:8px"><input type="checkbox" id="lkH"> Masquer la bannière rouge d’alerte de journaux (pour moi seulement, sur cet appareil)</label>
        <label>Lien de paiement (https, fournisseur de paiement)</label><div class="row"><input id="pcU" class="grow" placeholder="https://…"><button class="ghost lite" id="pcUS">Enregistrer</button></div>`;
      {const h=$('#lkH',C);if(h){h.checked=laHidden();h.onchange=()=>{try{localStorage.setItem('cm_hidela_'+S.me.id,h.checked?'1':'0')}catch(e){}logAlertCheck();toast(h.checked?'Bannière d’alerte masquée':'Bannière d’alerte affichée')}}}
      rpcd('log_keep_get').then(n=>{const i=$('#lkN',C);if(i)i.value=n}).catch(()=>{});
      C.onclick=async e=>{const t=e.target;try{
        if(t.id==='pcGo'){const items=$('#pcAll',C).checked?['*']:$$('.pcI:checked',C).map(x=>x.value);const mx=$('#pcM',C).value;await rpcd('promo_create',{p_code:$('#pcC',C).value,p_pct:+$('#pcP',C).value,p_items:items,p_max:mx?+mx:null,p_from:$('#pcF',C).value?new Date($('#pcF',C).value).toISOString():null,p_until:$('#pcE',C).value?new Date($('#pcE',C).value).toISOString():null,p_per_user:$('#pcU1',C).value?+$('#pcU1',C).value:null,p_badge:$('#pcB',C).value.trim()||null,p_purchase:$('#pcPu',C).checked});toast('Code créé');views.p()}
        else if(t.dataset&&t.dataset.t){await rpcd('promo_set',{p_code:t.dataset.t,p_active:t.dataset.a==='1'});views.p()}
        else if(t.id==='lkS'){await rpcd('log_keep_set',{p_n:+$('#lkN',C).value});toast('Rétention enregistrée')}
        else if(t.id==='lkA'){logAlertOpen()}
        else if(t.id==='pcUS'){await rpcd('pay_cfg_set',{p_url:$('#pcU',C).value.trim()});toast('Lien enregistré')}
      }catch(x){toast(errMsg(x))}}},
    w:()=>{C.innerHTML=`<p class="muted">Réservé aux demandes d’indemnisation et aux erreurs. Chaque action est journalisée.</p>
      <div class="row"><input id="tkU" placeholder="@utilisateur" class="grow"><button class="ghost lite" id="tkSee">Voir</button></div><div id="tkInfo" class="muted"></div>
      <div class="row"><input id="tkN" type="number" step="0.5" placeholder="Montant (négatif pour retirer)" class="grow"><input id="tkR" placeholder="Raison" class="grow"><button id="tkGo">Appliquer</button></div>
      <label>Badges</label><div class="row"><select id="tkB" class="grow">${allB.map(b=>`<option value="${b}">${esc(BN[b])}</option>`).join('')}</select><button class="ghost lite" id="tkBG">Donner</button><button class="ghost lite" id="tkBT">Retirer</button></div>
      <label>Articles</label><div class="row"><select id="tkI" class="grow">${items.map(i=>`<option value="${i.code}">${esc(i.name)}</option>`).join('')}</select><button class="ghost lite" id="tkGive">Donner</button><button class="ghost lite" id="tkTake">Retirer</button></div>`;
      const U=()=>$('#tkU',C).value;
      const see=async()=>{try{const d=await rpcd('admin_wallet',{p_username:U()});$('#tkInfo',C).textContent=`Solde : ${nfmt(d.balance)} · badges : ${(d.badges||[]).map(b=>BN[b]||b).join(', ')||'aucun'} · articles : ${(d.items||[]).join(', ')||'aucun'}`}catch(x){toast(errMsg(x))}};
      $('#tkSee',C).onclick=see;
      $('#tkGo',C).onclick=async()=>{try{const d=await rpcd('admin_tokens',{p_username:U(),p_amount:+$('#tkN',C).value,p_reason:$('#tkR',C).value});toast('Nouveau solde : '+nfmt(d));see()}catch(x){toast(errMsg(x))}};
      const bg=give=>async()=>{try{await rpcd('admin_badge',{p_username:U(),p_code:$('#tkB',C).value,p_give:give});toast('Fait');see()}catch(x){toast(errMsg(x))}};
      $('#tkBG',C).onclick=bg(true);$('#tkBT',C).onclick=bg(false);
      const it=give=>async()=>{try{await rpcd('admin_item',{p_username:U(),p_code:$('#tkI',C).value,p_give:give});toast('Fait');see()}catch(x){toast(errMsg(x))}};
      $('#tkGive',C).onclick=it(true);$('#tkTake',C).onclick=it(false)},
    b:async()=>{const l=await rpcd('bug_list');C.innerHTML=l.length?l.map(b=>`<div class="refbox"><b>${esc(b.title)}</b> <span class="muted">@${esc(b.user)} · ${esc(fmtDt(b.at))}</span><p style="white-space:pre-wrap">${esc(b.body)}</p><div class="row end"><button class="ghost lite" data-bn="${b.id}">Refuser</button><button class="lite" data-by="${b.id}">Approuver (+55)</button></div></div>`).join(''):'<p class="muted">Aucun signalement en attente.</p>';
      C.onclick=async e=>{const d=e.target.dataset||{};const id=d.by||d.bn;if(!id)return;try{await rpcd('bug_review',{p_id:+id,p_approve:!!d.by});toast('Fait');views.b()}catch(x){toast(errMsg(x))}}},
    c:async()=>{const l=await rpcd('contest_list');C.innerHTML=l.length?l.map(c=>`<div class="refbox"><b>${c.user?'@'+esc(c.user):'(compte pas encore créé)'}</b> <span class="muted">parrain @${esc(c.referrer||'?')} · ${esc(fmtDt(c.at))}</span><p style="white-space:pre-wrap">${esc(c.reason)}</p><details><summary>Cache transmis</summary><pre style="max-height:240px;overflow:auto;font-size:11px">${esc(JSON.stringify(c.cache,null,1))}</pre></details><div class="row end"><button class="ghost lite" data-cn="${c.id}">Refuser</button><button class="lite" data-cy="${c.id}">Accepter (verser les jetons)</button></div></div>`).join(''):'<p class="muted">Aucune contestation en attente.</p>';
      C.onclick=async e=>{const d=e.target.dataset||{};const id=d.cy||d.cn;if(!id)return;try{await rpcd('contest_decide',{p_id:+id,p_approve:!!d.cy});toast('Fait');views.c()}catch(x){toast(errMsg(x))}}},
    d:async()=>{const l=await rpcd('badge_requests_list');C.innerHTML=l.length?l.map(r=>`<div class="refbox"><b>@${esc(r.user)}</b> demande <b>${esc(BN[r.code]||r.code)}</b> <span class="muted">${esc(fmtDt(r.at))}</span><p style="white-space:pre-wrap">${esc(r.note)}</p><div class="row end"><button class="ghost lite" data-rn="${r.id}">Refuser</button><button class="lite" data-ry="${r.id}">Accorder</button></div></div>`).join(''):'<p class="muted">Aucune demande.</p>';
      C.onclick=async e=>{const d=e.target.dataset||{};const id=d.ry||d.rn;if(!id)return;try{await rpcd('badge_request_decide',{p_id:+id,p_ok:!!d.ry});toast('Fait');views.d()}catch(x){toast(errMsg(x))}}}
  };
  $('#tkT',box).onclick=e=>{const s=e.target.dataset&&e.target.dataset.s;if(!s)return;$$('#tkT [data-s]',box).forEach(b=>b.classList.toggle('on',b.dataset.s===s));C.onclick=null;views[s]()};
  views.w();
}

