/* ================= Lot 4 : présence « Vu », sessions en direct (1 appel + 1 jeu par conversation) ================= */
var SEEN={t:0};
async function seenRefresh(ids){
  try{if(!ids||!ids.length||Date.now()-(SEEN.t||0)<4000)return;SEEN.t=Date.now();
    const {data,error}=await sb.rpc('profiles_seen',{p_ids:ids});if(error||!data)return;
    let ch=false;data.forEach(r=>{const p=S.profiles.get(r.id);if(p&&r.last_seen&&(!p.last_seen||new Date(r.last_seen)>new Date(p.last_seen))){p.last_seen=r.last_seen;ch=true}});
    if(ch&&typeof renderHeader==='function')renderHeader()}catch(e){}
}
(function seenBeat(){
  const beat=()=>{try{if(S.me&&S.me.id)sb.from('profiles').update({last_seen:new Date().toISOString()}).eq('id',S.me.id).then(()=>{})}catch(e){}};
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')beat()});
  window.addEventListener('pagehide',beat);window.addEventListener('beforeunload',beat);
})();

/* ----- registre serveur : 1 appel + 1 jeu par conversation ----- */
function liveStart(ss){
  const kind=ss.game==='appel'?'call':'game';
  sb.rpc('live_start',{p_conv:ss.conv,p_kind:kind,p_session:ss.id,p_game:ss.game}).then(({error})=>{
    if(error){if(S.sess===ss){toast(errMsg(error));ss.liveBad=true;leaveSession(true)}return}
    ss.liveOk=true;
    ss.beatT=setInterval(()=>{if(S.sess!==ss){clearInterval(ss.beatT);return}sb.rpc('live_beat',{p_session:ss.id}).then(()=>{})},30000);
    if(S.sess!==ss)sb.rpc('live_end',{p_session:ss.id}).then(()=>{});
  });
}
function liveEnd(ss){clearInterval(ss.beatT);if(ss.isHost&&!ss.liveBad)sb.rpc('live_end',{p_session:ss.id}).then(()=>{liveRefresh()})}
var LIVE={list:[],conv:null};
async function liveRefresh(){
  const c=cur();const bar=document.getElementById('liveBar');
  if(!c||c.kind==='self'){if(bar)bar.hidden=true;return}
  let list=[];try{const {data}=await sb.rpc('live_list',{p_conv:c.id});list=data||[]}catch(e){}
  if(cur()!==c)return;LIVE.list=list;LIVE.conv=c.id;livePaint();
}
function livePaint(){
  try{ensureProfiles([].concat(...LIVE.list.map(l=>l.users||[]))).then(callCardsPaint)}catch(e){}callCardsPaint();
  const c=cur();let bar=document.getElementById('liveBar');
  if(!bar){const m=document.getElementById('msgs');if(!m)return;bar=document.createElement('div');bar.id='liveBar';bar.hidden=true;m.parentNode.insertBefore(bar,m);
    bar.onclick=e=>{const b=e.target.closest('[data-j]');if(b)liveJoin(b.dataset.j)}}
  const mine=S.sess&&S.sess.conv;
  const rows=(c&&LIVE.conv===c.id?LIVE.list:[]).filter(l=>!(S.sess&&S.sess.id===l.session));
  if(!rows.length){bar.hidden=true;bar.innerHTML='';return}
  bar.innerHTML=rows.map(l=>{const g=GAMES[l.game];return l.kind==='call'
    ?`<div class="lv-r"><span class="lv-dot"></span><span class="grow">Appel en cours · ${esc(l.host_name||'')}</span><button data-j="${esc(l.session)}">Rejoindre l’appel</button></div>`
    :`<div class="lv-r"><span class="lv-dot g"></span><span class="grow">${esc(g?g.name:'Jeu')} en cours · ${esc(l.host_name||'')}</span><button data-j="${esc(l.session)}">${l.phase==='live'?'Rejoindre (observateur)':'Rejoindre'}</button></div>`}).join('');
  bar.hidden=false;
}
function callCardsPaint(){
  document.querySelectorAll('.callmsg').forEach(el=>{
    const l=(LIVE.conv===(S.active||null)?LIVE.list:[]).find(x=>x.session===el.dataset.s&&x.kind==='call');
    const mine=S.sess&&S.sess.id===el.dataset.s;
    if(!l){el.innerHTML=`<div class="cm-t">${ic('phone',16)} Appel terminé</div>`;return}
    const us=(l.users||[]).map(id=>S.profiles.get(id)).filter(Boolean);
    el.innerHTML=`<div class="cm-t">${ic('phone',16)} Appel en cours · ${esc(l.host_name||'')}</div><div class="cm-av">${us.slice(0,8).map(p=>av(p.avatar_url,p.username,'xs')).join('')}${us.length>8?`<span class="muted">+${us.length-8}</span>`:''}</div><button class="cm-j" data-j="${esc(l.session)}" ${mine?'disabled':''}>${mine?'Vous êtes dans l’appel':'Rejoindre l’appel'}</button>`;
  });
}
document.addEventListener('click',e=>{const b=e.target.closest&&e.target.closest('.callmsg [data-j]');if(b&&!b.disabled)liveJoin(b.dataset.j)});
function liveJoin(sid){
  const l=LIVE.list.find(x=>x.session===sid);if(!l)return;
  if(S.pend&&!S.sess&&!S.call){clearTimeout(S.pend.to);S.pend=null;hideRing()}
  if(S.sess||S.call||S.pend)return toast('Quittez d’abord votre activité en cours');
  joinSession({id:l.session,game:l.game,conv:LIVE.conv,host:l.host});
  if(l.kind==='game'&&l.phase==='live')S.sess.spec=true;
}
(function liveWatch(){
  let ch=null;
  const start=()=>{if(ch||!window.sb||!S.me||!S.me.id)return;
    try{ch=sb.channel('live-watch').on('postgres_changes',{event:'*',schema:'public',table:'live_sessions'},()=>liveRefresh()).subscribe()}catch(e){ch=null}};
  setInterval(()=>{start();if(document.visibilityState==='visible')liveRefresh()},15000);
})();

/* ----- appel : démarrage, micro, partage d’écran, réduire, commandes dans la barre ----- */
function startCallLive(){
  const c=cur();if(!c)return;
  if(S.sess||S.call||S.pend)return toast('Une activité est déjà en cours');
  startSession('appel');
}
const ULAW=(()=>{const t=new Uint8Array(65536);for(let i=0;i<65536;i++){let s=(i<<16>>16),sign=s<0?0x80:0;if(s<0)s=-s;if(s>32635)s=32635;s+=132;let e=7;for(let m=0x4000;(s&m)===0&&e>0;e--,m>>=1);t[i]=~(sign|(e<<4)|((s>>(e+3))&0x0F))&0xFF}return t})();
const ULIN=(()=>{const t=new Int16Array(256);for(let i=0;i<256;i++){let u=~i&0xFF,sign=u&0x80,e=(u>>4)&7,m=u&0x0F,s=((m<<3)+132)<<e;s-=132;t[i]=sign?-s:s}return t})();
async function micToggle(){
  const ss=S.sess;if(!ss)return;const b=document.getElementById('rmMic');
  if(ss.mic){ss.mic.node.disconnect();ss.mic.src.disconnect();ss.mic.stream.getTracks().forEach(t=>t.stop());try{ss.mic.ctx.close()}catch(e){}ss.mic=null;b.classList.remove('on');b.textContent='Micro';rsend('mic',{u:S.me.id,on:false},ss);return}
  try{const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true},video:false});
    const ctx=new (window.AudioContext||window.webkitAudioContext)({sampleRate:16000});const src=ctx.createMediaStreamSource(stream);
    const node=ctx.createScriptProcessor(4096,1,1);node.onaudioprocess=e=>{
      if(S.sess!==ss||!ss.mic)return;const d=e.inputBuffer.getChannelData(0);let mx=0;const u8=new Uint8Array(d.length);
      for(let i=0;i<d.length;i++){const v=Math.max(-1,Math.min(1,d[i]));if(Math.abs(v)>mx)mx=Math.abs(v);u8[i]=ULAW[(v*32767)&0xFFFF]}
      if(mx<0.015)return;let s='';for(let i=0;i<u8.length;i+=0x8000)s+=String.fromCharCode.apply(null,u8.subarray(i,i+0x8000));
      rsend('maud',{u:S.me.id,d:btoa(s)},ss)};
    src.connect(node);node.connect(ctx.destination);ss.mic={ctx,src,node,stream};
    b.classList.add('on');b.textContent='Micro actif';rsend('mic',{u:S.me.id,on:true},ss)}
  catch(e){toast('Micro inaccessible : '+errMsg(e))}
}
function micPlay(o){
  const ss=S.sess;if(!ss||o.u===S.me.id||ss.deaf)return;
  try{const bin=atob(o.d),n=bin.length;ss.pl=ss.pl||{};
    const p=ss.pl[o.u]||(ss.pl[o.u]={ctx:ss.plCtx||(ss.plCtx=new (window.AudioContext||window.webkitAudioContext)({sampleRate:16000})),t:0});
    const ctx=p.ctx;if(ctx.state==='suspended')ctx.resume();
    const buf=ctx.createBuffer(1,n,16000),ch=buf.getChannelData(0);for(let i=0;i<n;i++)ch[i]=ULIN[bin.charCodeAt(i)]/32768;
    const sr=ctx.createBufferSource();sr.buffer=buf;sr.connect(ctx.destination);const now=ctx.currentTime;
    if(p.t<now+0.02||p.t>now+1.2)p.t=now+0.12;sr.start(p.t);p.t+=buf.duration;
    const t=document.querySelector(`#rmTiles .tile[data-u="${o.u}"]`);if(t){t.classList.add('talk');clearTimeout(p.k);p.k=setTimeout(()=>t.classList.remove('talk'),450)}}catch(e){}
}
async function screenToggle(){
  const ss=S.sess;if(!ss)return;const b=document.getElementById('rmScr');
  if(ss.scr){clearInterval(ss.scr.t);ss.scr.stream.getTracks().forEach(t=>t.stop());ss.scr=null;b.classList.remove('on');b.textContent='Écran';rsend('scr',{u:S.me.id,off:1},ss);screenShow(S.me.id,null);return}
  if(!navigator.mediaDevices||!navigator.mediaDevices.getDisplayMedia)return toast('Partage d’écran non pris en charge sur cet appareil');
  try{const stream=await navigator.mediaDevices.getDisplayMedia({video:{width:{ideal:1280}},audio:false});
    const v=document.createElement('video');v.muted=true;v.srcObject=stream;await v.play();const cv=document.createElement('canvas');
    const tick=async()=>{if(S.sess!==ss||!ss.scr||!v.videoWidth||ss.scrBusy)return;ss.scrBusy=true;
      try{const w=Math.min(800,v.videoWidth),h=Math.round(w*v.videoHeight/v.videoWidth);cv.width=w;cv.height=h;cv.getContext('2d').drawImage(v,0,0,w,h);const i=cv.toDataURL('image/jpeg',.5);screenShow(S.me.id,i);await rsend('scr',{u:S.me.id,i},ss)}catch(e){}ss.scrBusy=false};
    ss.scr={stream,t:setInterval(tick,700)};stream.getVideoTracks()[0].onended=()=>{if(S.sess===ss&&ss.scr)screenToggle()};
    b.classList.add('on');b.textContent='Partage actif'}
  catch(e){if(e&&e.name!=='NotAllowedError')toast('Partage impossible : '+errMsg(e))}
}
function screenShow(u,img){
  const ss=S.sess;if(!ss)return;let box=document.getElementById('rmScr0');const side=document.querySelector('#room .rm-side');
  if(!img){if(ss.scrU===u){ss.scrU=null;if(box)box.remove()}return}
  ss.scrU=u;if(!box){box=document.createElement('div');box.id='rmScr0';box.innerHTML='<div class="scr-h"></div><img alt="">';side.insertBefore(box,side.firstChild);
    box.onclick=()=>box.classList.toggle('big')}
  box.firstChild.textContent='Écran de '+nmOf(u)+' · toucher pour agrandir';box.lastChild.src=img;
}
function roomMini(on){
  if(on&&S.sess&&EV.rest(S.sess.conv,'minimize_call')){toast('Réduire est interdit dans ce tournoi');EV.viol(S.sess.conv,'minimize_call');return}
  const r=document.getElementById('room');if(!r)return;r.classList.toggle('mini',on);const b=document.getElementById('rmMin');if(b)b.textContent=on?'Agrandir':'Réduire';
  if(!on){r.style.left=r.style.top=r.style.right=r.style.bottom='';}
}
function liveRoomOpen(ss){
  const r=document.getElementById('room');if(!r)return;const isCall=ss.game==='appel';r.classList.toggle('call',isCall);
  const act_=r.querySelector('.rm-actions');
  const mk=(id,t,fn)=>{const b=document.createElement('button');b.className='rbtn';b.id=id;b.textContent=t;b.onclick=fn;act_.insertBefore(b,document.getElementById('rmQuit'));return b};
  mk('rmMin','Réduire',()=>roomMini(!r.classList.contains('mini')));
  if(isCall){mk('rmMic','Micro',micToggle);mk('rmScr','Écran',screenToggle);mk('rmPres','Présenter',presToggle)}
  if(ss.spec){const cb=document.getElementById('rmCam');if(cb)cb.hidden=true;const hb=document.getElementById('rmHand');if(hb)hb.hidden=true;const sy=document.getElementById('rmSay');if(sy)sy.disabled=true;
    const sub=document.getElementById('rmSub');if(sub)sub.textContent='Observateur'}
  // mini fenêtre déplaçable
  const top=r.querySelector('.rm-top');let d=null;
  top.addEventListener('pointerdown',e=>{if(!r.classList.contains('mini')||e.target.closest('button'))return;const b=r.getBoundingClientRect();d={x:e.clientX-b.left,y:e.clientY-b.top};top.setPointerCapture(e.pointerId)});
  top.addEventListener('pointermove',e=>{if(!d)return;r.style.right=r.style.bottom='auto';r.style.left=Math.max(0,Math.min(innerWidth-120,e.clientX-d.x))+'px';r.style.top=Math.max(0,Math.min(innerHeight-60,e.clientY-d.y))+'px'});
  top.addEventListener('pointerup',()=>{d=null});
  // commandes dans la barre de texte en direct
  const inp=document.getElementById('rmSay');
  inp.addEventListener('keydown',async e=>{
    if(e.key!=='Enter')return;const t=inp.value.trim();if(!t)return;
    if(/^(!|[a-z0-9]+\/)\S/i.test(t)){e.preventDefault();inp.value='';ss.say[S.me.id]='';updateSay(S.me.id);rsend('say',{u:S.me.id,t:''},ss);
      const c=S.convs.get(ss.conv);try{await botRoute(c,t,{})}catch(er){toast(errMsg(er))}}
  });
  inp.placeholder='Écrire en direct, ou une commande (!… , vl/…) puis Entrée';
  livePaint();
}

/* ================= Corrections : appels (fin automatique, hôte transféré), rejoindre, jetons des .catch ================= */
let AUTHTOK=null;
(async()=>{try{const {data}=await sb.auth.getSession();AUTHTOK=data&&data.session&&data.session.access_token||null}catch(e){}try{sb.auth.onAuthStateChange((e,s)=>{AUTHTOK=s&&s.access_token||null})}catch(e){}})();
const bgRpc=(fn,body)=>{try{sb.rpc(fn,body).then(()=>{},()=>{})}catch(e){}};   // le builder supabase n'a pas de .catch
function beaconRpc(fn,body){
  try{if(!AUTHTOK)return;fetch(SUPABASE_URL+'/rest/v1/rpc/'+fn,{method:'POST',keepalive:true,headers:{apikey:SUPABASE_KEY,Authorization:'Bearer '+AUTHTOK,'Content-Type':'application/json'},body:JSON.stringify(body)}).catch(()=>{})}catch(e){}
}
liveStart=function(ss){
  const kind=ss.game==='appel'?'call':'game';
  sb.rpc('live_start',{p_conv:ss.conv,p_kind:kind,p_session:ss.id,p_game:ss.game}).then(({error})=>{
    if(error){if(S.sess===ss){toast(errMsg(error));ss.liveBad=true;leaveSession(true)}return}
    ss.liveOk=true;liveBeatStart(ss);
    if(kind==='call'&&ss.isHost){const c=S.convs.get(ss.conv);if(c)sendPayload(c,{k:'call',c:{s:ss.id,h:S.me.id}}).catch(()=>{})}
    if(S.sess!==ss)bgRpc('live_leave',{p_session:ss.id});
  });
};
function liveBeatStart(ss){
  clearInterval(ss.beatT);
  ss.beatT=setInterval(()=>{if(S.sess!==ss){clearInterval(ss.beatT);return}bgRpc('live_beat',{p_session:ss.id})},10000);
}
liveEnd=function(ss){clearInterval(ss.beatT);if(ss.liveBad)return;try{sb.rpc('live_leave',{p_session:ss.id}).then(()=>{liveRefresh()},()=>{})}catch(e){}};
const _sg=startGame;startGame=function(){_sg.apply(this,arguments);const ss=S.sess;if(ss&&ss.isHost&&ss.phase==='live')bgRpc('live_phase',{p_session:ss.id,p_phase:'live'})};
const _js=joinSession;
joinSession=function(p){
  _js.apply(this,arguments);const ss=S.sess;if(!ss)return;
  sb.rpc('live_join',{p_session:p.id,p_spec:false}).then(({error})=>{if(error&&S.sess===ss){toast(errMsg(error));leaveSession(false);return}liveBeatStart(ss)},()=>{});
};
liveJoin=function(sid){
  const l=LIVE.list.find(x=>x.session===sid);if(!l)return;
  if(S.pend&&!S.sess&&!S.call){clearTimeout(S.pend.to);S.pend=null;hideRing()}
  if(S.sess||S.call||S.pend)return toast('Quittez d’abord votre activité en cours');
  if(l.host===S.me.id&&(l.members||0)<=1){      // son propre ancien appel, abandonné : on le termine pour en relancer un
    try{sb.rpc('live_leave',{p_session:l.session}).then(()=>{liveRefresh();toast('Ancienne session terminée : vous pouvez la relancer')},()=>{})}catch(e){}return;
  }
  joinSession({id:l.session,game:l.game,conv:LIVE.conv,host:l.host});
};
/* l'hôte d'un appel qui part passe la main ; l'appel s'arrête quand il n'y a plus personne (serveur) */
const _ls=leaveSession;
leaveSession=function(notify){
  const ss=S.sess;
  if(ss&&notify&&ss.isHost&&ss.game==='appel'){
    const others=ss.players.filter(u=>u!==S.me.id&&!(ss.away&&ss.away[u])).sort();
    if(others.length){rsend('host',{u:S.me.id,to:others[0]},ss);ss.isHost=false}
  }
  return _ls.apply(this,arguments);
};
function roomHostEv(o){
  const ss=S.sess;if(!ss||ss.game!=='appel'||!o||!o.to||(o.u&&o.u!==ss.host))return;
  const old=ss.host;ss.host=o.to;
  if(o.to===S.me.id&&!ss.isHost){
    ss.isHost=true;ss.invited=new Set();ss.declined=new Set();ss.players=ss.players.filter(x=>x!==old);
    delete ss.cams[old];delete ss.say[old];if(ss.away)delete ss.away[old];
    const t=document.querySelector(`#rmTiles .tile[data-u="${old}"]`);if(t)t.remove();pushState();
  }
}
const _at=awayTick;
awayTick=function(){
  const ss=S.sess;
  if(ss&&ss.game==='appel'&&ss.away){
    for(const u of Object.keys(ss.away)){
      if(Date.now()-ss.away[u]<AWAY_MS||u!==ss.host)continue;
      delete ss.away[u];                                   // l'hôte a disparu : le premier participant présent reprend
      const alive=ss.players.filter(x=>x!==u&&!ss.away[x]).sort();const nh=alive[0]||S.me.id;ss.host=nh;
      if(nh===S.me.id){ss.isHost=true;ss.invited=new Set();ss.declined=new Set();ss.players=ss.players.filter(x=>x!==u);delete ss.cams[u];delete ss.say[u];
        const t=document.querySelector(`#rmTiles .tile[data-u="${u}"]`);if(t)t.remove();pushState()}
    }
  }
  return _at.apply(this,arguments);
};
/* fermeture de la page : quitter proprement (l'hôte d'appel passe la main, le serveur est prévenu) */
window.addEventListener('pagehide',e=>{
  const ss=S.sess;if(!ss||e.persisted)return;
  beaconRpc('live_leave',{p_session:ss.id});
  try{leaveSession(true)}catch(x){}
});
/* observateur : les boutons caméra/main/texte se désactivent selon l'état reçu de l'hôte */
const _rr=renderRoom;
renderRoom=function(){
  _rr.apply(this,arguments);const ss=S.sess;if(!ss)return;
  const sp=!!ss.spec&&!(GAMES[ss.game]||{}).p2p;
  ['rmCam','rmHand'].forEach(i=>{const b=document.getElementById(i);if(b)b.hidden=sp});
  const sy=document.getElementById('rmSay');if(sy)sy.disabled=sp;
  const sub=document.getElementById('rmSub');if(sp&&sub)sub.textContent='Observateur';
};

/* ================= Lot 4 : menu clic droit des messages, plus ancien non lu ================= */
function scrollOldestUnread(c,base){
  /* ouverture : la vue est directement sur le message le plus récent, sans défilement visible.
     La liste reste masquée le temps du placement, puis la position est maintenue en bas pendant que les images se chargent. */
  const box=document.getElementById('msgs');if(!box)return;
  box.style.scrollBehavior='auto';S.stick=true;S._prog=1;box.scrollTop=box.scrollHeight;box.style.visibility='';
  let user=false;const off=()=>{user=true};['wheel','touchstart','keydown','pointerdown'].forEach(ev=>box.addEventListener(ev,off,{once:true,passive:true}));
  const end=Date.now()+1800,id=c.id;
  const f=()=>{if(user||!cur()||cur().id!==id||Date.now()>end){S._prog=0;return}box.scrollTop=box.scrollHeight;requestAnimationFrame(f)};requestAnimationFrame(f);
}
function onMsgUpd(row){
  if(!row||row.id==null)return;const l=S.msgs[row.conversation_id];if(!l)return;
  const i=l.findIndex(x=>x.id===row.id);if(i<0)return;const c=S.convs.get(row.conversation_id);
  decode(c,{...row}).then(r=>{l[i]=Object.assign(l[i],r);if(S.active===row.conversation_id)renderMsgs(false)})
}
var MENU={el:null};
function menuClose(){if(MENU.el){MENU.el.remove();MENU.el=null}}
function menuOpen(x,y,items){
  menuClose();const el=document.createElement('div');el.className='ctxm';
  el.innerHTML=items.map((it,i)=>it==='-'?'<hr>':`<button data-i="${i}" class="${it.danger?'danger':''}">${esc(it.t)}</button>`).join('');
  document.body.appendChild(el);MENU.el=el;MENU.t=Date.now();
  const w=el.offsetWidth,h=el.offsetHeight;el.style.left=Math.max(6,Math.min(x,innerWidth-w-6))+'px';el.style.top=Math.max(6,Math.min(y,innerHeight-h-6))+'px';
  el.onclick=e=>{const b=e.target.closest('[data-i]');if(!b)return;const it=items[+b.dataset.i];menuClose();it.f()};
}
document.addEventListener('pointerdown',e=>{if(MENU.el&&!e.target.closest('.ctxm'))menuClose()},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape')menuClose()});
window.addEventListener('scroll',()=>{if(Date.now()-(MENU.t||0)>400)menuClose()},true);window.addEventListener('resize',menuClose);
function msgPlain(m){const d=m._d||{};return d.k==='text'||(!d.k&&d.t)?String(d.t||''):(d.u||'')}
function msgItems(c,m){
  const d=m._d||{},mine=m.sender_id===S.me.id,age=Date.now()-new Date(m.created_at).getTime(),it=[];
  const txt=msgPlain(m);
  if(txt)it.push({t:'Copier le texte',f:()=>linkCopy(txt)});
  const fw=d.k==='text'||d.u||(d.k==='image'&&c.mode==='clear'&&d.p);
  if(fw&&!d.bot&&!m.whisper_to)it.push({t:'Transférer…',f:()=>msgForward(c,m)});
  const self=[...S.convs.values()].find(x=>x.kind==='self');
  if(fw&&self&&c.kind!=='self'&&!m.whisper_to)it.push({t:'Enregistrer dans le bloc-notes',f:()=>msgSend(self,m).then(()=>toast('Enregistré dans le bloc-notes')).catch(e=>toast(errMsg(e)))});
  if(mine&&m.kind==='text'&&!d.bot&&age<5*60000)it.push({t:'Modifier',f:()=>msgEdit(c,m)});
  it.push('-');
  it.push({t:'Supprimer pour moi',danger:true,f:async()=>{const {error}=await sb.rpc('msg_hide',{p_msg:m.id});if(error)return toast(errMsg(error));const l=S.msgs[c.id];const i=l.findIndex(x=>x.id===m.id);if(i>=0)l.splice(i,1);renderMsgs(false);renderList()}});
  if(mine&&age<15*60000)it.push({t:'Supprimer pour tous',danger:true,f:async()=>{if(!confirm('Supprimer ce message pour tout le monde ?'))return;const {error}=await sb.rpc('msg_delete_all',{p_msg:m.id});if(error)return toast(errMsg(error))}});
  it.push({t:'Signaler ce message',danger:true,f:()=>reportModal(c,m.id)});
  it.push('-');
  it.push({t:'Envoyé '+new Date(m.created_at).toLocaleString('fr-CA',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})+(m.edited_at?' · modifié':''),f:()=>{}});
  return it;
}
async function msgSend(c2,m){const d=m._d||{};const pl={k:d.k==='text'?'text':(d.u?'image':d.k),t:d.t,u:d.u,p:d.p,m:d.m,fwd:1};if(d.u)pl.k='image';await sendPayload(c2,pl)}
function msgForward(c,m){
  const list=[...S.convs.values()].filter(x=>x.id!==c.id||true);
  const mm=modal(`<h3>Transférer à…</h3><div class="fw-l">${list.map(x=>`<button class="ghost fw-i" data-c="${x.id}">${esc(x.kind==='self'?'Bloc-notes':convTitle(x))}</button>`).join('')}</div><div class="row end"><button class="ghost" data-x>Annuler</button></div>`);
  mm.addEventListener('click',async e=>{const b=e.target.closest('[data-c]');if(!b)return;const c2=S.convs.get(b.dataset.c);mm.close();
    if(c2.mode!==c.mode&&(m._d||{}).p)return toast('Ce média ne peut pas être transféré vers ce type de conversation');
    try{await msgSend(c2,m);toast('Message transféré')}catch(er){toast(errMsg(er))}});
}
function msgEdit(c,m){
  const mm=modal(`<h3>Modifier le message</h3><textarea id="meT" rows="4" maxlength="4000" style="width:100%">${esc((m._d||{}).t||'')}</textarea><div class="row end"><button class="ghost" data-x>Annuler</button><button id="meOk">Enregistrer</button></div>`);
  $('#meOk',mm).onclick=async()=>{const v=$('#meT',mm).value.trim();if(!v)return;
    let body=v;if(c.mode!=='clear'){const pl={...(m._d||{}),t:v};delete pl._;body=await encText(c.id,JSON.stringify(pl))}
    const {data,error}=await sb.rpc('msg_edit',{p_msg:m.id,p_body:body});if(error)return toast(errMsg(error));
    m.body=body;m.edited_at=(data&&data.edited_at)||new Date().toISOString();m._d={...(m._d||{}),t:v};mm.close();renderMsgs(false)};
}
(function menuInit(){
  const box=document;
  const show=(x,y,t)=>{const r=t.closest('.mrow[data-mid]');if(!r)return false;const c=cur();if(!c)return false;
    const m=(S.msgs[c.id]||[]).find(z=>String(z.id)===r.dataset.mid);if(!m||m.kind==='system')return false;menuOpen(x,y,msgItems(c,m));return true};
  box.addEventListener('contextmenu',e=>{if(!e.target.closest('#msgs')||e.target.closest('a,audio,video'))return;if(show(e.clientX,e.clientY,e.target))e.preventDefault()});
  let lp=null;
  box.addEventListener('touchstart',e=>{if(!e.target.closest('#msgs'))return;const t=e.touches[0];lp=setTimeout(()=>{show(t.clientX,t.clientY,e.target)},550)},{passive:true});
  ['touchend','touchmove','touchcancel'].forEach(ev=>box.addEventListener(ev,()=>clearTimeout(lp),{passive:true}));
})();

