/* ================= Lot 4 : jeux Wikipédia (Akinateur, EEMMTT, WikiFight) ================= */
const WK={
  imgs(u){u=String(u||'');const m=u.match(/^(https:\/\/upload\.wikimedia\.org\/wikipedia\/[a-z]+\/thumb\/.+\/)(\d+)px-([^\/]+)$/);if(!m)return[u];
    const full=m[1].replace('/thumb/','/').replace(/\/$/,'');return[u,m[1]+'330px-'+m[3],m[1]+'250px-'+m[3],m[1]+'500px-'+m[3],full]},
  imgH(u,cls){const a=WK.imgs(u);if(!a[0])return `<span class="${cls||'emt-i'} noimg"></span>`;
    return `<img class="${cls||'emt-i'}" alt="" crossorigin="anonymous" referrerpolicy="no-referrer" loading="eager" decoding="async" src="${esc(a[0])}" data-o="${esc(a[0])}" data-alt="${esc(a.slice(1).join(' '))}" onerror="var d=this.dataset,l=(d.alt||'').split(' ').filter(Boolean);if(l.length){d.alt=l.slice(1).join(' ');this.src=l[0]}else if(this.crossOrigin&&!d.nc){d.nc=1;this.removeAttribute('crossorigin');this.src=d.o}else{this.style.visibility='hidden'}">`},  qs:o=>Object.entries(o).map(([k,v])=>k+'='+encodeURIComponent(v)).join('&'),
  async j(u){const r=await fetch(u);if(!r.ok)throw new Error('Wikipédia indisponible ('+r.status+')');return r.json()},
  async search(lang,q){q=String(q||'').trim();if(q.length<2)return[];
    const d=await WK.j(`https://${lang}.wikipedia.org/w/api.php?`+WK.qs({action:'opensearch',search:q,limit:8,namespace:0,format:'json',origin:'*'}));
    return(d[1]||[]).map((t,i)=>({t,d:(d[2]||[])[i]||''}))},
  async summary(lang,t){const d=await WK.j(`https://${lang}.wikipedia.org/api/rest_v1/page/summary/`+encodeURIComponent(String(t).replace(/ /g,'_')));
    return{t:d.title||t,x:String(d.extract||'').slice(0,400),img:(d.thumbnail&&d.thumbnail.source)||null}},
  async html(lang,t){const r=await fetch(`https://${lang}.wikipedia.org/api/rest_v1/page/html/`+encodeURIComponent(String(t).replace(/ /g,'_'))+'?redirect=true');if(!r.ok)throw new Error('Page introuvable');return r.text()},
  async celebs(n){
    const pool=CELEBS.slice().sort(()=>Math.random()-.5),out=[];
    for(let i=0;i<pool.length&&out.length<n;i+=Math.max(8,n*2)){
      const part=pool.slice(i,i+Math.max(8,n*2));
      try{const d=await WK.j('https://en.wikipedia.org/w/api.php?'+WK.qs({action:'query',titles:part.join('|'),prop:'pageimages|langlinks',piprop:'thumbnail',pithumbsize:500,lllang:'fr',lllimit:50,redirects:1,format:'json',formatversion:2,origin:'*'}));
        for(const p of ((d.query&&d.query.pages)||[])){const fr=p.langlinks&&p.langlinks[0]&&(p.langlinks[0].title||p.langlinks[0]['*']);const img=p.thumbnail&&p.thumbnail.source;if(fr&&img&&out.length<n&&!out.some(o=>o.t===fr))out.push({t:fr,img})}}
      catch(e){if(!out.length)throw e}
    }
    if(out.length<n)throw new Error('Impossible de récupérer assez de personnalités');
    return out.sort(()=>Math.random()-.5);
  },
  render(html){
    const doc=new DOMParser().parseFromString(html,'text/html');
    const canon=(doc.querySelector('title')||{}).textContent||'';
    doc.querySelectorAll('script,style,link,meta,base,iframe,object,embed,form,input,button,noscript,video,audio,.mw-editsection,.navbox,.navbox-styles,.hatnote,.mbox-small,.metadata,.noprint,sup.mw-ref,.mw-references-wrap,ol.references,.reflist,.bandeau-container,.homonymie,.gallery,.sistersitebox,figure[typeof*="Extension"]').forEach(e=>e.remove());
    const OK=new Set(['class','src','alt','colspan','rowspan','data-t','width','height']);
    doc.body.querySelectorAll('*').forEach(e=>{
      if(e.tagName==='A'){
        const h=e.getAttribute('href')||'';let t=null;
        if(/^\.\/[^#?]+/.test(h)||(e.getAttribute('rel')||'').includes('mw:WikiLink')){try{t=decodeURIComponent(h.replace(/^\.\//,'').replace(/[#?].*$/,'')).replace(/_/g,' ')}catch(x){t=null}}
        if(t&&!/^(Fichier|Image|Catégorie|Category|File|Aide|Help|Spécial|Special|Wikipédia|Wikipedia|Portail|Portal|Modèle|Template|Discussion|Talk|Projet|Utilisateur|User|Média|Media|Livre|Draft|Brouillon|Module):/i.test(t)&&!e.querySelector('img')){const s=doc.createElement('span');s.className='wk-l';s.dataset.t=t;while(e.firstChild)s.appendChild(e.firstChild);e.replaceWith(s);return}
        const s=doc.createElement('span');while(e.firstChild)s.appendChild(e.firstChild);e.replaceWith(s);return}
      if(e.tagName==='IMG'){let s=e.getAttribute('src')||'';if(s.startsWith('//'))s='https:'+s;if(!/^https:\/\/upload\.wikimedia\.org\//.test(s)){e.remove();return}e.setAttribute('src',s);e.removeAttribute('srcset');e.setAttribute('loading','lazy')}
      [...e.attributes].forEach(a=>{if(!OK.has(a.name))e.removeAttribute(a.name)});
    });
    return{title:canon,html:doc.body.innerHTML};
  }
};
