      ov.innerHTML=`<div style="background:var(--card,#1c1f26);color:var(--text,#eee);padding:18px;border-radius:12px;width:min(92vw,360px);text-align:center"><b>Écraser : ${esc(name)}</b><p class="muted" style="margin:6px 0">Cliquez quand le pilon passe dans la zone verte. 6 coups réussis.</p><div id="cB" style="position:relative;height:34px;background:#0006;border-radius:8px;margin:10px 0;overflow:hidden"><div id="cZ" style="position:absolute;top:0;bottom:0;background:#2fbf7155;border-left:2px solid #2fbf71;border-right:2px solid #2fbf71"></div><div id="cP" style="position:absolute;top:3px;width:12px;height:28px;border-radius:5px;background:#e8e2cf"></div></div><svg id="cS" viewBox="0 0 100 40" width="160" height="64"></svg><div id="cT" class="muted">0 / 6</div><div class="row end" style="margin-top:10px"><button class="ghost" id="cX">Abandonner</button><button id="cH">Écraser</button></div></div>`;document.body.appendChild(ov);
