  /* réanimation : 5 niveaux, 3 battements chacun, cliquer dans la zone verte ; une erreur recommence le niveau */
  const rescueGame=async(un,nm)=>{try{await rpcd('smoke_rescue_start',{p_username:un})}catch(e){toast(errMsg(e));return}
    const m=modal(`<div class="fxRs"><h3>Réanimer ${esc(nm||un)}</h3><div class="muted" id="rsInfo"></div><div class="dots" id="rsDots"></div><div class="tr" id="rsTr"><div class="zn" id="rsZn"></div><div class="mk" id="rsMk"></div></div><button id="rsGo" style="min-width:200px">Compresser (clic ou Espace)</button><div id="rsMsg" class="muted" style="min-height:18px"></div></div>`);m.setAttribute('data-fxkeep','');
    const W=[.2,.16,.13,.1,.075],PER=[1.7,1.5,1.3,1.15,1.0],tr=m.querySelector('#rsTr'),zn=m.querySelector('#rsZn'),mk=m.querySelector('#rsMk'),msg=m.querySelector('#rsMsg'),inf=m.querySelector('#rsInfo'),dots=m.querySelector('#rsDots');
    let lv=0,hit=0,miss=0,zx=.4,t0=performance.now(),pause=0,raf=0,done=false,pos=0;const newZ=()=>{zx=.08+Math.random()*(.84-W[lv]);zn.style.left=(zx*100)+'%';zn.style.width=(W[lv]*100)+'%'};
    const paint=()=>{dots.innerHTML=[0,1,2].map(i=>`<i class="${i<hit?'on':''}"></i>`).join('');inf.textContent='Niveau '+(lv+1)+' / 5 · erreurs '+miss+' / 4'};
    const fin=async ok=>{if(done)return;done=true;cancelAnimationFrame(raf);document.removeEventListener('keydown',kd,true);try{const r=await rpcd('smoke_rescue_done',{p_username:un,p_ok:ok});if(ok&&r&&r.saved)toast(esc(nm||un)+' est sauvé');else toast(ok?'Trop tard…':'La réanimation a échoué')}catch(e){toast(errMsg(e))}m.close()};
    const press=()=>{if(done||pause>performance.now())return;const hitOk=pos>=zx&&pos+.012<=zx+W[lv]+.012;
      if(hitOk){hit++;msg.textContent='Bon battement';pause=performance.now()+2200;if(hit>=3){hit=0;lv++;if(lv>=5){paint();return fin(true)}msg.textContent='Niveau '+lv+' réussi';}newZ()}
      else{miss++;hit=0;msg.textContent='Raté : le niveau recommence';pause=performance.now()+1200;if(miss>=4)return fin(false)}paint()};
    const kd=e=>{if(e.code==='Space'||e.key===' '){e.preventDefault();e.stopPropagation();press()}};document.addEventListener('keydown',kd,true);
    m.querySelector('#rsGo').onclick=press;newZ();paint();
    const loop=n=>{if(done)return;if(!m.isConnected){fin(false);return}const per=PER[lv]*1000,ph=((n-t0)%(per*2))/per;pos=ph<1?ph:2-ph;mk.style.left=(pos*100)+'%';raf=requestAnimationFrame(loop)};raf=requestAnimationFrame(loop);
    const mo=new MutationObserver(()=>{if(!m.isConnected&&!done){fin(false);mo.disconnect()}});mo.observe(document.body,{childList:true})};
